L["TALENT_GUIDE_NOTE"] = "Verde = hecho, amarillo = siguiente, gris '?' = no encontrado en tu árbol de talentos (los nombres de los talentos pueden cambiar con los parches del juego)."
L["ABOUT_TEXT"] = "LazyGCore sugiere tu siguiente habilidad usando listas de prioridad investigadas de World of Warcraft: Forever para las nueve clases, y te guía al elegir talentos.\n\nForever funciona con el motor moderno de WoW, que oculta parte de la información de combate a los addons (salud del objetivo, algunas auras, el registro de combate). LazyGCore lo lee todo a través de una capa segura: cuando el juego oculta un valor, LazyGCore recurre a su propio seguimiento de lanzamientos o a las comprobaciones reactivas de 'utilizable' de Blizzard en lugar de adivinar.\n\nSi alguna sugerencia parece incorrecta, cambia el motor a 'LazyGCore + respaldo Blizzard' o 'Combate asistido Blizzard', y usa /lazygcore check y /lazygcore status para informar de lo que muestra tu cliente.\n\nComandos: /lazygcore, /lazygcore talents, /lazygcore toggle, /lazygcore spec <name / auto>, /lazygcore engine <lazygcore / hybrid / blizzard>."

