L["Healthstone"] = "Piedra de salud"
L["Low health: instant heal (shared 2 min cooldown)."] = "Poca salud: sanación instantánea (tiempo de reutilización compartido de 2 min)."
L["No Healthstone in your bags (costs a Soul Shard)."] = "No tienes Piedra de salud en las bolsas (cuesta un Fragmento de alma)."
L["Dungeons before Master Demonologist: Blood Pact + Firebolt."] = "En mazmorras antes de Maestro demonogista: Pacto de sangre + Descarga de Fuego."
L["Low health: Bear, then Frenzied Regeneration."] = "Poca salud: forma de oso y luego Regeneración frenética."
L["Hard-hitting filler with Improved Starfire."] = "Relleno contundente con Fuego estelar mejorado."
L["Threat on every mob, less damage taken."] = "Amenaza en cada enemigo, menos daño recibido."

L["Cheetah / Pack is on in combat: every hit dazes you."] = "Guepardo / Manada activo en combate: cada golpe te atonta."
L["You have aggro - drop threat."] = "Tienes el aggro: reduce la amenaza."
L["Melee: more dodge, and dodges enable Mongoose Bite."] = "Cuerpo a cuerpo: más esquiva, y esquivar habilita Mordedura de mangosta."
L["Group health hidden - mouse over who to heal"] = "Salud del grupo oculta: pasa el ratón sobre quien quieras sanar"
L["Immune to attacks and spells for 6-8s, but you can't attack; Forbearance after."] = "Inmune a ataques y hechizos durante 6-8 s, pero no puedes atacar; luego Paciencia."
L["Hard hits incoming: +30% block for 10s."] = "Llegan golpes fuertes: +30% de bloqueo durante 10 s."
L["+30% block; every block deals Holy damage and threat to the pack."] = "+30% de bloqueo; cada bloqueo inflige daño Sagrado y amenaza a la manada."
L["Instant damage between Auto Shots."] = "Daño instantáneo entre Tiros automáticos."
L["Out of melee: sting it while you close in."] = "Fuera de cuerpo a cuerpo: aplica la picadura mientras te acercas."
L["Hit plus a Fire DoT."] = "Golpe más un DoT de Fuego."
L["One more DoT while the target lives long enough."] = "Un DoT más mientras el objetivo viva lo suficiente."
L["Heal up between pulls."] = "Sánate entre pulls."
L["Pack is down - back to Cat."] = "El grupo de enemigos ha caído: vuelve a forma felina."
L["You tank this group: Bear Form."] = "Tanqueas este grupo: forma de oso."
L["Feral in groups:"] = "Feral en grupo:"
L["Bear (tank)"] = "Oso (tanque)"
L["Cat (damage)"] = "Felino (daño)"
L["Pool energy for Ghostly Strike."] = "Acumula energía para Golpe fantasmal."
L["Renew yourself: heals over 15s while you keep casting."] = "Renovar sobre ti: sana durante 15 s mientras sigues lanzando."
L["Instant hit plus a 12s Fire DoT."] = "Golpe instantáneo más un DoT de Fuego de 12 s."
L["Regrowth is ticking - Healing Touch for the rest."] = "Recrecimiento ya está activo: Toque curativo para el resto."
L["Low health: absorb the next hits."] = "Poca salud: absorbe los próximos golpes."
L["Your main nuke."] = "Tu hechizo de daño principal."
L["Damage and a 40% slow on everything in front of you."] = "Daño y ralentización del 40% a todo lo que tienes delante."
L["Shadow DoT: keep it ticking."] = "DoT de Sombras: mantenlo activo."
L["Channeled: hits everything in the area for 6s."] = "Canalizado: golpea todo lo que hay en la zona durante 6 s."
L["At your feet: Fire damage to every mob within 10 yd."] = "A tus pies: daño de Fuego a todos los enemigos a 10 m."
L["At your feet: burns the first mob to reach it."] = "A tus pies: quema al primer enemigo que la pise."
L["Weapon-damage kick, 8s cooldown (+30% run speed)."] = "Patada con daño de arma, 8 s de reutilización (+30% de velocidad de carrera)."
L["21s bleed: keep it on targets that live."] = "Sangrado de 21 s: mantenlo en objetivos que aguanten."
L["Single target: your hardest-hitting shot."] = "Un solo objetivo: tu disparo más fuerte."
L["Hits up to 4 enemies around you."] = "Golpea hasta 4 enemigos a tu alrededor."
L["Open with Charge, then Berserker Stance."] = "Abre con Embestir y luego Actitud rabiosa."
L["Before Whirlwind (36) Fury fights here: Rend and Overpower."] = "Antes de Huracán (36) Furia lucha aquí: Desgarrar y Abrumar."
L["Pool energy for Backstab."] = "Acumula energía para Puñalada."
L["In danger: quick heal on yourself."] = "En peligro: sanación rápida sobre ti."
L["Hurt: Renew yourself and keep casting."] = "Herido: Renovar sobre ti y sigue lanzando."
L["Shadowform filler."] = "Relleno en Forma de las Sombras."
L["Filler: out-damages the wand."] = "Relleno: hace más daño que la varita."
L["Group health hidden: a cheap heal on the tank (mouse over whoever needs it)."] = "Salud del grupo oculta: una sanación barata al tanque (pasa el ratón por encima de quien la necesite)."
-- ============================================================================
-- OPTION TOOLTIPS (hover explanations of the options window controls)
-- ============================================================================
L["Turns LazyGCore on or off. Off hides the display and stops all suggestions, action bar glows, alerts and sounds."] = "Activa o desactiva LazyGCore. Desactivado oculta la pantalla y detiene todas las sugerencias, brillos de la barra de acción, alertas y sonidos."
L["Keeps the display where it is. While locked the icon ignores the mouse, so clicks pass through to the game; unlock it to drag the display somewhere else."] = "Mantiene la pantalla en su sitio. Bloqueado, el icono ignora el ratón y los clics pasan al juego; desbloquéalo para arrastrar la pantalla a otro lugar."
L["Shows the LazyGCore button on the minimap. Click: these options. Ctrl+Click: show or hide the display. Shift+Click: Stats window. Alt+Click: talents."] = "Muestra el botón de LazyGCore en el minimapa. Clic: estas opciones. Ctrl+Clic: mostrar u ocultar la pantalla. Mayús+Clic: ventana de estadísticas. Alt+Clic: talentos."
L["Where the suggestions come from. LazyGCore priorities: LazyGCore's own rotation for your spec. LazyGCore + Blizzard fallback: LazyGCore first, and only when LazyGCore has nothing to suggest, Blizzard's Assisted Combat pick is shown. Blizzard Assisted Combat: Blizzard's pick on the main icon, LazyGCore's next spells in the queue."] = "De dónde salen las sugerencias. Prioridades de LazyGCore: la rotación propia de LazyGCore para tu especialización. LazyGCore + respaldo Blizzard: primero LazyGCore y, solo cuando LazyGCore no tiene nada que sugerir, se muestra la elección del Combate asistido Blizzard. Combate asistido Blizzard: la elección de Blizzard en el icono principal y los siguientes hechizos de LazyGCore en la cola."
L["Which spec's rotation LazyGCore follows on this character. Auto picks the talent tree with the most points (the Leveling rotation before you spend any). Pick a spec to force it; it goes back to Auto when you switch talent specs."] = "Qué rotación de especialización sigue LazyGCore en este personaje. Auto elige el árbol de talentos con más puntos (la rotación de Subida de nivel antes de gastar ninguno). Elige una especialización para forzarla; vuelve a Auto cuando cambias de especialización de talentos."
L["Shows the rotation display. Off hides it (with its alerts) everywhere, even in combat, while the action bar glow keeps following the suggestions. Same as /lazygcore toggle."] = "Muestra la pantalla de rotación. Desactivado la oculta (con sus alertas) en todas partes, incluso en combate, mientras el brillo de la barra de acción sigue las sugerencias. Igual que /lazygcore toggle."
L["Keeps the display on screen out of combat too. Off (default): it shows in combat, plus the two cases below."] = "Mantiene la pantalla visible también fuera de combate. Desactivado (por defecto): se muestra en combate y en los dos casos de abajo."
L["Out of combat, also show the display while you target an enemy, so you see the opener before the pull. Only applies when Show out of combat is off."] = "Fuera de combate, muestra también la pantalla mientras tienes un enemigo como objetivo, para que veas la apertura antes del pull. Solo se aplica si Mostrar fuera de combate está desactivado."
L["Out of combat, also show the display when it suggests a missing buff, pet, poison or weapon imbue, and hide it again once done. Only applies when Show out of combat is off and Suggest buffs & pets (Combat page) is on."] = "Fuera de combate, muestra también la pantalla cuando sugiere un buff, mascota, veneno o imbuición de arma que falta, y la vuelve a ocultar al terminar. Solo se aplica si Mostrar fuera de combate está desactivado y Sugerir buffs y mascotas (página Combate) está activado."
L["Out of combat, hide the display while there is nothing to suggest instead of showing the LazyGCore logo. Only applies when Show out of combat is on."] = "Fuera de combate, oculta la pantalla cuando no hay nada que sugerir en lugar de mostrar el logo de LazyGCore. Solo se aplica si Mostrar fuera de combate está activado."
L["Shows the spell part of the display: main icon, cooldown icon, history, queue, spell name and reason. Off hides those; the ring (swing timer), warning line, alerts, buff tracker and DPS strip stay, and the action bar glow still works."] = "Muestra la parte de hechizos de la pantalla: icono principal, icono de reutilización, historial, cola, nombre del hechizo y motivo. Desactivado los oculta; el anillo (temporizador de golpe), la línea de aviso, las alertas, el rastreador de buffs y la franja de DPS se mantienen, y el brillo de la barra de acción sigue funcionando."
L["Color of the ring around the main icon, the DPS strip accent and the Auto action bar glow. Auto (Match Spec) uses your spec's color."] = "Color del anillo alrededor del icono principal, del acento de la franja de DPS y del brillo Auto de la barra de acción. Auto (Según Espec.) usa el color de tu especialización."
L["Look of LazyGCore's windows: these options, the Stats window and the talent windows. Default is the classic WoW gold style."] = "Aspecto de las ventanas de LazyGCore: estas opciones, la ventana de estadísticas y las ventanas de talentos. Predeterminado es el estilo dorado clásico de WoW."
L["Size of the whole rotation display: icons, text and DPS strip. Does not change LazyGCore's windows. Default 1.0."] = "Tamaño de toda la pantalla de rotación: iconos, texto y franja de DPS. No cambia las ventanas de LazyGCore. Por defecto 1.0."
L["Size of the main spell icon in pixels, before Scale. The cooldown icon grows with it. Default 72."] = "Tamaño del icono principal en píxeles, antes de la Escala. El icono de reutilización crece con él. Por defecto 72."
L["Opacity of the whole rotation display: icons, text, warning line, alerts and DPS strip. 1 = fully visible."] = "Opacidad de toda la pantalla de rotación: iconos, texto, línea de aviso, alertas y franja de DPS. 1 = totalmente visible."
L["Opacity of the spell icons only: the main icon and its ring, the cooldown icon, the spell history and the queue (NEXT). The text stays fully visible."] = "Opacidad solo de los iconos de hechizo: el icono principal y su anillo, el icono de reutilización, el historial de hechizos y la cola (SIG). El texto sigue totalmente visible."
L["Dark box behind the rotation display. 0 (default) = no box; higher = a more solid box."] = "Recuadro oscuro detrás de la pantalla de rotación. 0 (por defecto) = sin recuadro; más alto = un recuadro más opaco."
L["Moves the rotation display back to its default spot below the middle of the screen."] = "Devuelve la pantalla de rotación a su posición por defecto, algo por debajo del centro."
L["Sets Spec template back to Auto and detects your spec from your talents again."] = "Devuelve Plantilla de especialización a Auto y vuelve a detectar tu especialización a partir de tus talentos."
L["Opens or closes the floating Stats window (DPS, parse estimate, live stats)."] = "Abre o cierra la ventana flotante de estadísticas (DPS, estimación de parse, estadísticas en vivo)."
L["Opens or closes the Talent Guide window with the recommended talent build for your spec."] = "Abre o cierra la ventana Guía de talentos con la build de talentos recomendada para tu especialización."
L["Shows the key bound to the suggested spell in the top-right corner of the main icon, read from your action bars."] = "Muestra la tecla asignada al hechizo sugerido en la esquina superior derecha del icono principal, leída de tus barras de acción."
L["Shows a gold star in the top-left corner of the main icon when the suggestion comes from a proc."] = "Muestra una estrella dorada en la esquina superior izquierda del icono principal cuando la sugerencia viene de un proc."
L["Shows 'Out of Range' over the main icon and greys it out when your target is out of range of the suggested spell."] = "Muestra 'Fuera de alcance' sobre el icono principal y lo pone en gris cuando tu objetivo está fuera del alcance del hechizo sugerido."
L["Shows a badge with the enemy count in the bottom-left corner of the main icon when enough enemies are near for AoE."] = "Muestra una insignia con el número de enemigos en la esquina inferior izquierda del icono principal cuando hay suficientes enemigos cerca para AoE."
L["Shows the global cooldown sweep over the main icon after each cast. Off by default."] = "Muestra el barrido del tiempo de reutilización global sobre el icono principal tras cada lanzamiento. Desactivado por defecto."
L["Healers: shows the name of the group member a heal is suggested for at the bottom of the main icon (not for yourself or your target)."] = "Sanadores: muestra en la parte inferior del icono principal el nombre del miembro del grupo al que se sugiere sanar (no si eres tú o tu objetivo)."
L["Shows a smaller icon right of the main icon for your next major cooldown, racial or on-use trinket: green pulse when ready, grey while it recharges. Off: cooldowns go into the queue instead."] = "Muestra un icono más pequeño a la derecha del icono principal con tu próxima reutilización importante, racial o abalorio de uso: pulso verde cuando está lista, gris mientras se recarga. Desactivado: las reutilizaciones van a la cola."
L["Size of the cooldown icon compared to the main icon (0.65 = 65%). Only applies when Cooldown icon is on."] = "Tamaño del icono de reutilización respecto al icono principal (0.65 = 65%). Solo se aplica si Icono de reutilización está activado."
L["Shows your last casts as small icons left of the main icon (PREV), newest nearest to it."] = "Muestra tus últimos lanzamientos como iconos pequeños a la izquierda del icono principal (PREV), el más reciente junto a él."
L["How many past casts to show. Only applies when Spell history is on."] = "Cuántos lanzamientos anteriores mostrar. Solo se aplica si Historial de hechizos está activado."
L["Size of the history icons in pixels. Only applies when Spell history is on."] = "Tamaño de los iconos del historial en píxeles. Solo se aplica si Historial de hechizos está activado."
L["On (default): history, main icon, cooldown icon and queue sit in one row. Off: the classic layout with the queue under the spell name."] = "Activado (por defecto): historial, icono principal, icono de reutilización y cola van en una sola fila. Desactivado: el diseño clásico con la cola bajo el nombre del hechizo."
L["Shows the spells LazyGCore expects to suggest after the current one (NEXT)."] = "Muestra los hechizos que LazyGCore espera sugerir después del actual (SIG)."
L["How many upcoming spells to show. Only applies when Priority queue is on."] = "Cuántos hechizos próximos mostrar. Solo se aplica si Cola de prioridad está activada."
L["Size of the queue icons in pixels. Only applies when Priority queue is on."] = "Tamaño de los iconos de la cola en píxeles. Solo se aplica si Cola de prioridad está activada."
L["Shows the name of the suggested spell under the main icon."] = "Muestra el nombre del hechizo sugerido bajo el icono principal."
L["Shows a short reason under the spell name: why this spell is suggested now, or why the rotation is paused."] = "Muestra un breve motivo bajo el nombre del hechizo: por qué se sugiere ahora este hechizo o por qué la rotación está en pausa."
L["Hides the spell name, the reason text and the DPS strip in one go (in the classic layout also the queue), whatever their own toggles say. Same as /lazygcore hidename."] = "Oculta de una vez el nombre del hechizo, el texto del motivo y la franja de DPS (en el diseño clásico también la cola), sin importar sus propias opciones. Igual que /lazygcore hidename."
L["Shows a health bar for your target above the main icon."] = "Muestra una barra de salud de tu objetivo encima del icono principal."
L["Shows the warning line above the icon: buff reminders, a suggested spell missing from your action bars, a lower rank on your bars, a paused rotation. Off hides all of them."] = "Muestra la línea de aviso encima del icono: recordatorios de buffs, un hechizo sugerido que falta en tus barras de acción, un rango inferior en tus barras, una rotación en pausa. Desactivado los oculta todos."
L["Out of combat, the warning line names a missing buff ('Recommended: ...') or one about to run out, with its time left. Only applies when Warning line is on."] = "Fuera de combate, la línea de aviso nombra un buff que falta ('Recomendado: ...') o uno a punto de acabarse, con su tiempo restante. Solo se aplica si Línea de aviso está activada."
L["Out of combat, the warning line lists up to three missing buffs ('Missing: ...') instead of naming only one. Only applies when Warning line is on."] = "Fuera de combate, la línea de aviso enumera hasta tres buffs que faltan ('Falta: ...') en lugar de nombrar solo uno. Solo se aplica si Línea de aviso está activada."
L["Shows a row of small icons under the display with your important buffs and your damage over time spells on the target, with their time left."] = "Muestra una fila de iconos pequeños bajo la pantalla con tus buffs importantes y tus hechizos de daño en el tiempo sobre el objetivo, con su tiempo restante."
L["Puts your active procs (Clearcasting, Shadow Trance, ...) first in the buff tracker. Only applies when Buff tracker is on."] = "Coloca tus procs activos (Conjuro libre, Trance de las Sombras, ...) los primeros en el rastreador de buffs. Solo se aplica si Rastreador de buffs está activado."
L["Fades the display while there is nothing to suggest. How far is set by Idle Transparency."] = "Atenúa la pantalla cuando no hay nada que sugerir. Cuánto se ajusta con Transparencia en inactividad."
L["Shows your melee swing (Hunters: Auto Shot) on the ring around the main icon; it pulses when the next swing is ready. Only applies when Show outline is on."] = "Muestra tu golpe cuerpo a cuerpo (Cazadores: Tiro automático) en el anillo alrededor del icono principal; parpadea cuando el siguiente golpe está listo. Solo se aplica si Mostrar borde está activado."
L["How visible the display stays while idle, as a share of Overall Transparency (0.3 = 30%). Only applies when Fade when idle is on."] = "Cuánto se ve la pantalla en inactividad, como proporción de Transparencia general (0.3 = 30%). Solo se aplica si Desvanecer en inactividad está activado."
L["Makes the action bar button of the suggested spell glow, so you find it at a glance."] = "Hace brillar el botón de la barra de acción del hechizo sugerido para que lo encuentres de un vistazo."
L["Look of that glow: LazyGCore glow (soft breathing glow), Marching ants, or Blizzard's own proc glow. Only applies when Glow the suggested spell is on."] = "Aspecto de ese brillo: Brillo de LazyGCore (brillo suave que respira), Hormigas o el brillo de proc propio de Blizzard. Solo se aplica si Resaltar el hechizo sugerido está activado."
L["Color of that glow. Auto (Match Spec) uses your theme color. Only applies when Glow the suggested spell is on."] = "Color de ese brillo. Auto (Según Espec.) usa el color de tu tema. Solo se aplica si Resaltar el hechizo sugerido está activado."
L["When the suggested spell is not on your action bars, the spellbook button and the spell inside the spellbook glow, so you can drag it to a bar."] = "Cuando el hechizo sugerido no está en tus barras de acción, brillan el botón del libro de hechizos y el hechizo dentro del libro, para que lo arrastres a una barra."
L["When a bar button holds a lower rank of the suggested spell, its glow turns orange and the warning line says which rank to put there."] = "Cuando un botón de barra tiene un rango inferior del hechizo sugerido, su brillo se vuelve naranja y la línea de aviso indica qué rango poner ahí."
L["Makes the action bar buttons of your spec's major cooldowns glow whenever they are ready, separately from the glow on the suggested spell."] = "Hace brillar los botones de la barra de acción de las reutilizaciones importantes de tu especialización cuando están listas, aparte del brillo del hechizo sugerido."
L["Color of the cooldown glow (default green). Only applies when Enable Cooldown Glow is on."] = "Color del brillo de reutilización (verde por defecto). Solo se aplica si Activar brillo de reutilización está activado."
L["Adds swing bars inside the main icon: main hand (gold), off hand (blue) and ranged (green, GO when ready)."] = "Añade barras de golpe dentro del icono principal: mano principal (dorado), mano secundaria (azul) y a distancia (verde, YA cuando está listo)."
L["Starts or stops a test swing so you can see the swing timer without fighting."] = "Inicia o detiene un golpe de prueba para que veas el temporizador de golpe sin combatir."
L["Includes your major offensive cooldowns, racials and on-use trinkets in the suggestions (in combat, with a target)."] = "Incluye en las sugerencias tus reutilizaciones ofensivas importantes, raciales y abalorios de uso (en combate, con objetivo)."
L["Suggests defensive spells and escapes when you are in danger: low health, stunned or feared. Also needed for the heal-your-pet and mana gem suggestions."] = "Sugiere hechizos defensivos y de escape cuando estás en peligro: salud baja, aturdido o con miedo. También es necesario para las sugerencias de sanar a tu mascota y de gema de maná."
L["Out of combat, the main icon suggests missing self-buffs, poisons and weapon imbues, calling or reviving your pet, and healing up between pulls."] = "Fuera de combate, el icono principal sugiere autobuffs, venenos e imbuiciones de arma que faltan, llamar o revivir a tu mascota y sanarte entre pulls."
L["Lets LazyGCore switch to your spec's AoE spells when at least AoE enemy threshold enemies are near."] = "Permite a LazyGCore cambiar a los hechizos AoE de tu especialización cuando hay cerca al menos tantos enemigos como indica Umbral de enemigos para AoE."
L["Allows AoE suggestions in battlegrounds and against players. Off by default, because every nearby player counts as an enemy. Only applies when Enable AoE suggestions is on."] = "Permite sugerencias AoE en campos de batalla y contra jugadores. Desactivado por defecto, porque cada jugador cercano cuenta como enemigo. Solo se aplica si Activar sugerencias AoE está activado."
L["How many enemies are needed for AoE suggestions (default 3). LazyGCore counts living enemies in combat within about 10 yards, or in range of your ranged AoE spell, from their nameplates, so enemy nameplates must be on."] = "Cuántos enemigos hacen falta para las sugerencias AoE (3 por defecto). LazyGCore cuenta los enemigos vivos en combate a unos 10 metros, o al alcance de tu hechizo AoE a distancia, por sus placas de nombre, así que las placas de nombre enemigas deben estar activadas."
L["Keeps the current suggestion for 0.3 seconds when another spell would briefly take over, so the icon doesn't flicker. Defensives always switch at once."] = "Mantiene la sugerencia actual 0.3 segundos cuando otro hechizo la sustituiría brevemente, para que el icono no parpadee. Las defensivas cambian siempre al instante."
L["Suggests your race's abilities, such as Berserking or Stoneform, along with your other spells."] = "Sugiere las habilidades de tu raza, como Iracundia o Petraforma, junto con tus otros hechizos."
L["Shows ready on-use trinkets in the cooldown slot, and your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "Muestra los abalorios de uso listos en el hueco de reutilización, y tu abalorio JcJ cuando estás aturdido o con miedo (con Sugerir defensivas activado)."
L["Healers: never suggest damage spells, not even solo."] = "Sanadores: no sugerir nunca hechizos de daño, ni siquiera en solitario."
L["Healers in a group: suggest damage spells while nobody needs healing. Solo, healers always get damage suggestions."] = "Sanadores en grupo: sugerir hechizos de daño mientras nadie necesite sanación. En solitario, los sanadores siempre reciben sugerencias de daño."
L["Healers: heal suggestions are for the friendly player under your mouse when there is one. Changes the suggestion target only - it never targets anything."] = "Sanadores: las sugerencias de sanación son para el jugador amistoso bajo el ratón cuando lo hay. Solo cambia el objetivo de la sugerencia: nunca selecciona ningún objetivo."
L["Shows a KICK! box to the left of the icon (left of the spell history when it shows) when your enemy target casts something you can interrupt and your interrupt is ready."] = "Muestra un recuadro ¡CORTA! a la izquierda del icono (a la izquierda del historial de hechizos cuando se muestra) cuando tu objetivo enemigo lanza algo que puedes interrumpir y tu interrupción está lista."
L["Shows a DEFENSIVE! box in combat when your health drops below Defensive Threshold and a defensive spell is ready."] = "Muestra un recuadro ¡DEFENSIVA! en combate cuando tu salud baja de Umbral defensivo y hay un hechizo defensivo listo."
L["Your health % below which the DEFENSIVE! box appears (default 35%). Only applies when Defensive Alerts is on."] = "Tu % de salud por debajo del cual aparece el recuadro ¡DEFENSIVA! (35% por defecto). Solo se aplica si Alertas defensivas está activado."
L["Out of combat, shows a PURGE box when your enemy target has a magic buff and your purge or dispel is ready."] = "Fuera de combate, muestra un recuadro PURGAR cuando tu objetivo enemigo tiene un buff mágico y tu purga o disipación está lista."
L["Shows EXECUTE! on the main icon while your enemy target is below Execute threshold. Only if you know Execute, Hammer of Wrath or Shadow Word: Death."] = "Muestra ¡EJECUTAR! en el icono principal mientras tu objetivo enemigo está por debajo de Umbral de ejecución. Solo si conoces Ejecutar, Martillo de cólera o Palabra de las Sombras: muerte."
L["Target health % below which EXECUTE! shows (default 20%). Only applies when Execute phase is on."] = "% de salud del objetivo por debajo del cual se muestra ¡EJECUTAR! (20% por defecto). Solo se aplica si Fase de ejecución está activada."
L["In combat, warns above the icon when your mana, rage or energy (and your pet's health) drops below the thresholds below."] = "En combate, avisa encima del icono cuando tu maná, ira o energía (y la salud de tu mascota) bajan de los umbrales de abajo."
L["Mana % below which the low mana warning shows (default 20%). Only applies when Low resource warnings is on."] = "% de maná por debajo del cual se muestra el aviso de maná bajo (20% por defecto). Solo se aplica si Avisos de recursos bajos está activado."
L["Rage below which the low rage warning shows (default 20). Only applies when Low resource warnings is on."] = "Ira por debajo de la cual se muestra el aviso de ira baja (20 por defecto). Solo se aplica si Avisos de recursos bajos está activado."
L["Energy below which the low energy warning shows (default 30). Only applies when Low resource warnings is on."] = "Energía por debajo de la cual se muestra el aviso de energía baja (30 por defecto). Solo se aplica si Avisos de recursos bajos está activado."
L["Pet health % below which the pet warning shows (default 30%). Only applies when Low resource warnings is on."] = "% de salud de la mascota por debajo del cual se muestra el aviso de mascota (30% por defecto). Solo se aplica si Avisos de recursos bajos está activado."
L["Shows the KICK! box for 3 seconds so you can see where it appears."] = "Muestra el recuadro ¡CORTA! durante 3 segundos para que veas dónde aparece."
L["Shows the DEFENSIVE! box for 3 seconds so you can see where it appears."] = "Muestra el recuadro ¡DEFENSIVA! durante 3 segundos para que veas dónde aparece."
L["Shows the PURGE box for 3 seconds so you can see where it appears."] = "Muestra el recuadro PURGAR durante 3 segundos para que veas dónde aparece."
L["Plays the alert sound when a KICK!, DEFENSIVE! or PURGE box appears, on low resource warnings and when a buff goes missing. Off by default."] = "Reproduce el sonido de alerta cuando aparece un recuadro ¡CORTA!, ¡DEFENSIVA! o PURGAR, con los avisos de recursos bajos y cuando falta un buff. Desactivado por defecto."
L["Silences every sound LazyGCore plays, including the proc and weapon buff sounds."] = "Silencia todos los sonidos de LazyGCore, incluidos los de procs y de buffs de arma."
L["Plays a sound when a proc becomes the suggestion. Works even with Sound alerts off."] = "Reproduce un sonido cuando un proc pasa a ser la sugerencia. Funciona incluso con Alertas sonoras desactivado."
L["Which sound the alerts play. Only applies when Sound alerts is on."] = "Qué sonido reproducen las alertas. Solo se aplica si Alertas sonoras está activado."
L["Plays the chosen alert sound once."] = "Reproduce una vez el sonido de alerta elegido."
L["How often suggestions are recalculated in combat. Faster reacts sooner but uses more CPU; casts, cooldowns and target changes refresh at once anyway. Default 20 per second."] = "Con qué frecuencia se recalculan las sugerencias en combate. Más rápido reacciona antes pero usa más CPU; los lanzamientos, reutilizaciones y cambios de objetivo actualizan al instante de todos modos. Por defecto 20 por segundo."
L["How often suggestions are recalculated out of combat. Slower saves CPU between fights; it is never faster than Update rate. Default 2 per second."] = "Con qué frecuencia se recalculan las sugerencias fuera de combate. Más lento ahorra CPU entre combates; nunca es más rápido que Frecuencia de actualización. Por defecto 2 por segundo."
L["Prints extra diagnostic messages to chat. Errors are reported either way; leave this off unless you are tracking down a problem."] = "Escribe mensajes de diagnóstico adicionales en el chat. Los errores se informan igualmente; déjalo desactivado salvo que estés buscando un problema."
L["Prints LazyGCore's status to chat: version, class, spec, engine and the settings that affect suggestions. Useful for bug reports."] = "Escribe el estado de LazyGCore en el chat: versión, clase, especialización, motor y los ajustes que afectan a las sugerencias. Útil para informar de errores."
L["Prints which spells of your class rotation you know and which are still missing from your spellbook."] = "Escribe qué hechizos de la rotación de tu clase conoces y cuáles faltan aún en tu libro de hechizos."
L["Turns on the game's Lua error pop-ups, to see errors from any addon."] = "Activa las ventanas de error Lua del juego, para ver errores de cualquier addon."
L["Turns off the game's Lua error pop-ups."] = "Desactiva las ventanas de error Lua del juego."
L["Prints the buffs and procs the buff tracker watches for your spec to chat."] = "Escribe en el chat los buffs y procs que vigila el rastreador de buffs para tu especialización."
L["Prints what LazyGCore suggests right now, and why, to chat."] = "Escribe en el chat qué sugiere LazyGCore ahora mismo y por qué."
L["Prints the details behind the DPS/HPS numbers to chat."] = "Escribe en el chat los detalles de las cifras de DPS/HPS."
L["Resets every account-wide LazyGCore setting to its default after you confirm. Your saved profiles and this character's spec, talent build and custom rotations are kept."] = "Restablece todos los ajustes de cuenta de LazyGCore a sus valores por defecto tras confirmar. Se conservan tus perfiles guardados y la especialización, la build de talentos y las rotaciones personalizadas de este personaje."
L["Makes the action bar buttons holding this spell glow for 5 seconds, to check that LazyGCore finds it. Empty box: the current suggestion."] = "Hace brillar durante 5 segundos los botones de la barra de acción que tienen este hechizo, para comprobar que LazyGCore lo encuentra. Cuadro vacío: la sugerencia actual."
L["Removes the test glow."] = "Quita el brillo de prueba."
L["Spell to test: type its name, or leave the box empty for the current suggestion. Enter or Test makes its action bar buttons glow."] = "Hechizo que probar: escribe su nombre o deja el cuadro vacío para la sugerencia actual. Intro o Probar hace brillar sus botones de la barra de acción."
L["Language of LazyGCore's text. Auto uses your game client's language. Applies after a UI reload."] = "Idioma de los textos de LazyGCore. Auto usa el idioma de tu cliente del juego. Se aplica tras recargar la UI."
L["Reloads the interface now, so a new language takes effect."] = "Recarga la interfaz ahora para que se aplique el nuevo idioma."
L["Sets every option on this page back to its default."] = "Devuelve todas las opciones de esta página a sus valores por defecto."
L["Switches between your custom rotation and LazyGCore's default priority for this spec."] = "Alterna entre tu rotación personalizada y la prioridad por defecto de LazyGCore para esta especialización."
L["When the spell is suggested. Conditions marked * are estimates in combat, because Forever hides health, mana and most auras there."] = "Cuándo se sugiere el hechizo. Las condiciones marcadas con * son estimaciones en combate, porque Forever oculta allí la salud, el maná y la mayoría de auras."
L["Adds the spell typed in the box to the end of your list, with the condition chosen beside it."] = "Añade el hechizo escrito en el cuadro al final de tu lista, con la condición elegida al lado."
L["Gives the entry selected in the list the spell, condition and values chosen here. A default rule becomes your own rule."] = "Aplica a la entrada seleccionada en la lista el hechizo, la condición y los valores elegidos aquí. Una regla predeterminada pasa a ser tu propia regla."
L["Fills the list with LazyGCore's default priority for your current spec, so you can edit it."] = "Rellena la lista con la prioridad por defecto de LazyGCore para tu especialización actual, para que puedas editarla."
L["Saves the list as this spec's saved rotation."] = "Guarda la lista como la rotación guardada de esta especialización."
L["Loads this spec's saved rotation into the list."] = "Carga en la lista la rotación guardada de esta especialización."
L["No saved rotation for this spec yet: use Save Custom first."] = "Aún no hay rotación guardada para esta especialización: usa primero Guardar personalizada."
L["Removes every spell from the list, after you confirm."] = "Quita todos los hechizos de la lista, tras confirmar."
L["Saves the list under the name typed in the box, so you can keep several rotations."] = "Guarda la lista con el nombre escrito en el cuadro, para que puedas tener varias rotaciones."
L["Your named rotations, with their spec and number of spells. Pick one, then Load or Delete it."] = "Tus rotaciones con nombre, con su especialización y número de hechizos. Elige una y luego Cargar o Eliminar."
L["Loads the named rotation picked beside it into the list."] = "Carga en la lista la rotación con nombre elegida al lado."
L["Deletes the named rotation picked beside it, after you confirm."] = "Elimina la rotación con nombre elegida al lado, tras confirmar."
L["Gives the named rotation picked below the name typed in the box."] = "Renombra la rotación con nombre elegida abajo con el nombre escrito en el cuadro."
L["LazyGCore suggests from your list above instead of its default priority for this spec. Defensives and the cooldown slot still work as usual."] = "LazyGCore sugiere a partir de tu lista de arriba en lugar de su prioridad por defecto para esta especialización. Las defensivas y el hueco de reutilización siguen funcionando como siempre."
L["When nothing in your list is ready, the default priority fills in. Only applies when Use Custom Rotation is on."] = "Cuando nada de tu lista está listo, se recurre a la prioridad por defecto. Solo se aplica si Usar rotación personalizada está activado."
L["Never suggest the spell typed in the box (also not in the cooldown slot or the cooldown glow)."] = "No sugerir nunca el hechizo escrito en el cuadro (tampoco en el hueco de reutilización ni en el brillo de reutilización)."
L["Lets the spell in the box, or the one selected in the list, be suggested again."] = "Permite que el hechizo del cuadro, o el seleccionado en la lista, vuelva a sugerirse."
L["Prints every excluded spell to chat."] = "Escribe en el chat todos los hechizos excluidos."
L["Removes every exclusion, after you confirm."] = "Quita todas las exclusiones, tras confirmar."
L["Turns LazyGCore off while you are in a battleground: no display, suggestions or glows there."] = "Desactiva LazyGCore mientras estás en un campo de batalla: allí no hay pantalla, sugerencias ni brillos."
L["Turns LazyGCore off while you are in an arena: no display, suggestions or glows there."] = "Desactiva LazyGCore mientras estás en una arena: allí no hay pantalla, sugerencias ni brillos."
L["Stops spell suggestions everywhere, not only in battlegrounds or arenas, but keeps the display with the DPS strip and swing timer."] = "Detiene las sugerencias de hechizos en todas partes, no solo en campos de batalla o arenas, pero mantiene la pantalla con la franja de DPS y el temporizador de golpe."
L["Shows an estimated parse percentile in the Stats window, based on this spec's benchmark numbers."] = "Muestra un percentil de parse estimado en la ventana de estadísticas, según las cifras de referencia de esta especialización."
L["Keeps your last fight's numbers on the DPS strip after combat ends instead of hiding it. Only applies when Show DPS/HPS is on."] = "Mantiene las cifras de tu último combate en la franja de DPS al terminar el combate en lugar de ocultarla. Solo se aplica si Mostrar DPS/HPS está activado."
L["Shows how your DPS compares to your personal best: the difference in DPS on the DPS strip, +/- % in the Stats window."] = "Muestra cómo se compara tu DPS con tu mejor marca personal: la diferencia de DPS en la franja de DPS y +/- % en la ventana de estadísticas."
L["Shows your rotation efficiency score on the DPS strip and in the Stats window."] = "Muestra tu puntuación de eficiencia de rotación en la franja de DPS y en la ventana de estadísticas."
L["When the DPS numbers start over. Each combat: every fight. Boss only: fights add up until a boss fight starts. Manual: only when you press Reset Now."] = "Cuándo se reinician las cifras de DPS. Cada combate: en cada combate. Solo jefe: los combates se suman hasta que empieza un combate contra un jefe. Manual: solo al pulsar Reiniciar ahora."
L["Clears the DPS numbers now (in Manual mode also Blizzard's damage meter)."] = "Borra ahora las cifras de DPS (en modo Manual también el medidor de daño de Blizzard)."
L["Prints your last 10 fights to chat."] = "Escribe en el chat tus últimos 10 combates."
L["Dark box behind the DPS strip. 0 (default) = no box. Only applies when Show DPS/HPS is on."] = "Recuadro oscuro detrás de la franja de DPS. 0 (por defecto) = sin recuadro. Solo se aplica si Mostrar DPS/HPS está activado."
L["Opacity of the floating Stats window."] = "Opacidad de la ventana flotante de estadísticas."
L["Adds a player's gear score and item level to their tooltip when you hover them."] = "Añade la puntuación de equipo y el nivel de objeto de un jugador a su descripción emergente al pasar el ratón por encima."
L["Rescans your gear and buffs and updates the boxes above."] = "Vuelve a analizar tu equipo y tus buffs y actualiza los recuadros de arriba."
L["Saves your current settings as a profile with the name typed in the box (replaces a profile of that name) and makes it active."] = "Guarda tus ajustes actuales como un perfil con el nombre escrito en el cuadro (sustituye un perfil con ese nombre) y lo activa."
L["Loads the profile selected in the list. Double-clicking a profile does the same."] = "Carga el perfil seleccionado en la lista. Hacer doble clic en un perfil hace lo mismo."
L["Deletes the selected profile, after you confirm. The Default profile can't be deleted."] = "Elimina el perfil seleccionado, tras confirmar. El perfil predeterminado no se puede eliminar."
L["Gives the selected profile the name typed in the box."] = "Renombra el perfil seleccionado con el nombre escrito en el cuadro."
L["Copies the selected profile (or the active one) to a new profile with the name typed in the box."] = "Copia el perfil seleccionado (o el activo) en un perfil nuevo con el nombre escrito en el cuadro."
L["When your detected spec changes, loads the profile you assigned to that spec with Use for this spec."] = "Cuando cambia tu especialización detectada, carga el perfil que asignaste a esa especialización con Usar para esta especialización."
L["Assigns the selected profile (or the active one) to your current spec."] = "Asigna el perfil seleccionado (o el activo) a tu especialización actual."
L["Removes the profile assigned to your current spec."] = "Quita el perfil asignado a tu especialización actual."
L["Puts the selected profile (or the active one) in the box as a text string you can copy and share. The active profile exports your current settings, including changes you have not saved."] = "Pone el perfil seleccionado (o el activo) en el cuadro como una cadena de texto que puedes copiar y compartir. El perfil activo exporta tu configuración actual, incluidos los cambios sin guardar."
L["Saves the profile string pasted in the box as a profile, named by the name box or by the string itself."] = "Guarda como perfil la cadena pegada en el cuadro, con el nombre del cuadro de nombre o el de la propia cadena."
L["While the talent frame is open, a green NEXT glow marks the next talent of your build, and the right spec tab and the Apply button are pointed out. Also prints a chat note when a point is free."] = "Con el marco de talentos abierto, un brillo verde SIG marca el siguiente talento de tu build, y se señalan la pestaña de especialización correcta y el botón Aplicar. También avisa en el chat cuando tienes un punto libre."
L["Makes the talent button on the micro menu glow while you have an unspent point for your build. Only applies when Glow the next talent in the talent frame is on."] = "Hace brillar el botón de talentos del micromenú mientras tengas un punto sin gastar para tu build. Solo se aplica si Resaltar el siguiente talento en el marco de talentos está activado."
L["Opens the Next Talent popup with the next talent of your build."] = "Abre la ventana de Siguiente talento con el siguiente talento de tu build."
L["Opens the build browser to pick another talent build for your spec."] = "Abre el explorador de builds para elegir otra build de talentos para tu especialización."
L["Shows this spec's recommended talent build below."] = "Muestra abajo la build de talentos recomendada para esta especialización."
L["Picks this spec's leveling build."] = "Elige la build de subida de nivel de esta especialización."
L["Picks this spec's PvE build (dungeons and raids)."] = "Elige la build JcE de esta especialización (mazmorras y bandas)."
L["Picks this spec's PvP build."] = "Elige la build JcJ de esta especialización."
L["Cycles this spec's build type: Leveling, PvE, PvP."] = "Alterna el tipo de build de esta especialización: subida de nivel, JcE, JcJ."
L["Picks which of this spec's talent builds the guide shows and follows."] = "Elige qué build de talentos de esta especialización muestra y sigue la guía."
L["Re-reads your talents and stops following a build started with Start Build."] = "Vuelve a leer tus talentos y deja de seguir una build iniciada con Iniciar build."
L["Opens the game's talent frame."] = "Abre el marco de talentos del juego."
L["Opens the game's macro window (/macro), where you drag the macros you created to your bars."] = "Abre la ventana de macros del juego (/macro), desde donde arrastras a tus barras las macros que has creado."
L["Updates every macro you already created from this page to its latest version."] = "Actualiza a su última versión todas las macros que ya creaste desde esta página."
L["Visibility"] = "Visibilidad"
L["Suggestions"] = "Sugerencias"
L["Troubleshooting"] = "Solución de problemas"
L["Hide name, reason and DPS strip"] = "Ocultar nombre, motivo y franja de DPS"
L["Buff reminder text"] = "Texto de recordatorio de buffs"
L["List all missing buffs"] = "Listar todos los buffs que faltan"
L["Suggest buffs & pets"] = "Sugerir buffs y mascotas"
L["Glow the suggested spell"] = "Resaltar el hechizo sugerido"
L["Saved rotations"] = "Rotaciones guardadas"
L["Balance: remind you to be in Moonkin Form out of combat, and suggest shifting back into it after a caster-form heal in combat"] = "Equilibrio: te recuerda estar en Forma de lechúcico lunar fuera de combate y sugiere volver a ella tras una sanación en forma de lanzador en combate"
L["Feral, in groups only (solo, LazyGCore picks the form itself). Bear always suggests Bear Form, Cat never does. Auto: Bear when you are in Bear Form, the group made you its tank, you run a Bear build or your last shift was into Bear; otherwise Cat"] = "Feral, solo en grupo (en solitario, LazyGCore elige la forma). Oso siempre sugiere Forma de oso, Felino nunca. Auto: Oso si estás en Forma de oso, el grupo te ha puesto de tanque, usas una build de Oso o tu último cambio fue a Oso; si no, Felino"
L["In Bear Form, in combat, suggest Frenzied Regeneration below this health %. Needs Suggest defensives on (Combat page)"] = "En Forma de oso, en combate, sugiere Regeneración frenética por debajo de este % de salud. Requiere Sugerir defensivas activado (página Combate)"
L["Suggest Hunter's Mark on elites, group targets, players and mobs above 60% health. Survival skips normal solo mobs it is about to melee, unless it has Expose Prey (which only procs on Marked targets)"] = "Sugiere Marca del cazador en élites, objetivos de grupo, jugadores y enemigos con más del 60% de salud. Supervivencia omite los enemigos normales en solitario a los que va a atacar cuerpo a cuerpo, salvo con Exponer presa (que solo se activa en objetivos marcados)"
L["Out of combat, remind you to call your pet, revive it if it died, or feed it when it is not happy. Skipped if you have the Lone Wolf talent"] = "Fuera de combate, te recuerda llamar a tu mascota, revivirla si ha muerto o darle de comer si no está contenta. Se omite si tienes el talento Lobo solitario"
L["Out of combat, remind you to put up your combat aspect: Aspect of the Hawk (Monkey before level 10); Survival uses Monkey until it learns Aspect of the Beast. Waits while Cheetah, Pack or Wild is on, and in combat warns when Cheetah or Pack is still on"] = "Fuera de combate, te recuerda activar tu aspecto de combate: Aspecto del halcón (Aspecto del mono antes del nivel 10); Supervivencia usa el del mono hasta aprender Aspecto de la bestia. Espera mientras esté activo Guepardo, Manada o lo Salvaje, y en combate avisa si Guepardo o Manada siguen activos"
L["In combat, suggest Mend Pet when your pet drops below this % (out of combat it reminds you below 60%). Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your pet takes. Needs Suggest defensives on (Combat page)"] = "En combate, sugiere Sanar mascota cuando tu mascota baja de este % (fuera de combate te lo recuerda por debajo del 60%). Forever oculta la salud de la mascota en combate: LazyGCore la estima a partir del daño y la sanación que recibe tu mascota. Requiere Sugerir defensivas activado (página Combate)"
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 15% of your Intellect as spell damage for 15 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "Arcano: acumulaciones de Explosión Arcana que reunir en élites, jefes, grupos y jugadores antes de Cólera Arcana y Misiles Arcanos. Cada acumulación añade un 15% de tu intelecto como daño con hechizos durante 15 segundos desde la primera Explosión, pero encarece la siguiente Explosión (los enemigos menores siempre reciben una Explosión)"
L["Fire with 3 points in Improved Scorch: keep this many Fire Vulnerability stacks up with Scorch on bosses, skull-marked targets and elites (solo or in a raid; never on players)"] = "Fuego con 3 puntos en Chamuscar mejorado: mantén este número de acumulaciones de Vulnerabilidad de Fuego con Chamuscar en jefes, objetivos marcados con calavera y élites (en solitario o en banda; nunca en jugadores)"
L["Suggest Evocation when you run low on mana: out of combat below the Evocation Threshold, in combat once you can't afford your filler spell"] = "Sugiere Evocación cuando te quedas sin maná: fuera de combate por debajo de Umbral de Evocación, en combate cuando ya no puedes pagar tu hechizo de relleno"
L["In combat, suggest a mana gem when you run low on mana, before Evocation (needs Suggest defensives and Suggest cooldowns on, Combat page). Out of combat, remind you to conjure one when your bags have none"] = "En combate, sugiere una gema de maná cuando te quedas sin maná, antes de Evocación (requiere Sugerir defensivas y Sugerir tiempos de reutilización activados, página Combate). Fuera de combate, te recuerda conjurar una cuando no tienes ninguna en las bolsas"
L["Suggest Evocation when mana is below this %. Out of combat only: Forever hides your mana in combat, so there Evocation is suggested once you can't afford your filler spell"] = "Sugiere Evocación cuando el maná está por debajo de este %. Solo fuera de combate: Forever oculta tu maná en combate, así que allí se sugiere Evocación cuando ya no puedes pagar tu hechizo de relleno"
L["Suggest Consecration in melee range when mana allows, mostly on packs and elites. Applies to every spec (Holy only when solo)"] = "Sugiere Consagración en rango cuerpo a cuerpo si el maná lo permite, sobre todo contra grupos de enemigos y élites. Se aplica a todas las especializaciones (Sagrado solo en solitario)"
L["Protection: on keeps Holy Shield up whenever you are in melee. Off: only against elites or when your health is below 50%"] = "Protección: activado mantiene Escudo Sagrado siempre que estés cuerpo a cuerpo. Desactivado: solo contra élites o cuando tu salud está por debajo del 50%"
L["Out of combat, remind you to put your blessing on yourself when it is missing or has under 1 minute left. Holy in a group: also Blessing of Kings on the ally you heal"] = "Fuera de combate, te recuerda ponerte tu bendición cuando falta o le queda menos de 1 minuto. Sagrado en grupo: también Bendición de los Reyes en el aliado al que sanas"
L["The blessing the reminder keeps on you (needs Blessing Reminder on). Auto: Wisdom for Holy, Kings for Protection, Might otherwise. Might is used until the chosen one is learned"] = "La bendición que el recordatorio mantiene en ti (requiere Recordatorio de Bendición activado). Auto: Sabiduría para Sagrado, Reyes para Protección y Poderío en los demás casos. Se usa Poderío hasta que aprendes la elegida"
L["Auto: the new Shadow Word: Pain lands right as the old one ends (recasting early throws away its remaining ticks). Or refresh when this many seconds remain. Applies to every spec while it deals damage"] = "Auto: el nuevo Palabra de las Sombras: Dolor llega justo cuando acaba el anterior (relanzarlo antes tira sus tics restantes). O renovarlo cuando queden estos segundos. Se aplica a todas las especializaciones mientras hacen daño"
L["Only suggest Shadow Word: Death while your own health is above this % (it hurts you if the target survives)"] = "Solo sugiere Palabra de las Sombras: muerte mientras tu propia salud esté por encima de este % (te daña si el objetivo sobrevive)"
L["Never suggest Fade. When off, Fade is suggested in a group as soon as you pull threat"] = "No sugerir nunca Desvanecer. Desactivado, se sugiere Desvanecer en grupo en cuanto atraes amenaza"
L["In combat, suggest Mind Blast every time it comes off cooldown. Off: the normal priority decides, and normal mobs often get your wand to save mana"] = "En combate, sugiere Explosión mental cada vez que termina su reutilización. Desactivado: decide la prioridad normal, y los enemigos normales suelen recibir la varita para ahorrar maná"
L["Combo points to build before Eviscerate. Auto: 5 with talents (4 before), and 4 on normal mobs while questing (3 below level 20) so they die sooner. A target about to die gets Eviscerate from 2 points"] = "Puntos de combo que acumular antes de Eviscerar. Auto: 5 con talentos (4 antes), y 4 contra enemigos normales en misiones (3 por debajo del nivel 20) para que mueran antes. Un objetivo a punto de morir recibe Eviscerar desde 2 puntos"
L["Keep Slice and Dice up (from 2 combo points, 4 for Combat) on targets above 25% health. Leveling and Combat skip normal mobs while questing; Assassination and Subtlety skip players. Off: never suggest it"] = "Mantén Hacer picadillo activo (desde 2 puntos de combo, 4 en Combate) en objetivos con más del 25% de salud. Subida de nivel y Combate omiten los enemigos normales en misiones; Asesinato y Sutileza omiten a los jugadores. Desactivado: nunca lo sugiere"
L["Auto: each spec's own choice (Assassination: Rupture on elites, Subtlety: on elites, groups and players, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "Auto: la elección de cada especialización (Asesinato: Ruptura en élites; Sutileza: en élites, grupos y jugadores; Combate y subida de nivel: solo Eviscerar). Ruptura: primero Ruptura siempre que falte en un objetivo con más del 35% de salud. Eviscerar: nunca Ruptura"
L["Assassination and Combat: in a group, suggest Vanish against an elite (while you don't hold threat) so you can use a stealth opener again. Subtlety has its own Vanish rule"] = "Asesinato y Combate: en grupo, sugiere Esfumar contra un élite (mientras no tengas la amenaza) para poder usar de nuevo una apertura en sigilo. Sutileza tiene su propia regla de Esfumar"
L["Suggest your damage and buff totems (Searing, Magma, Strength of Earth, water totems, totem sets), mostly on elites, groups and players; Magma Totem on packs. Off: only utility totems such as Stoneclaw, Grounding, Tremor and Mana Tide are still suggested"] = "Sugiere tus tótems de daño y de buff (Abrasador, Magma, Fuerza de la tierra, tótems de agua, conjuntos de tótems), sobre todo en élites, grupos y jugadores; Tótem de magma contra grupos de enemigos. Desactivado: solo se siguen sugiriendo tótems de utilidad como Garra de piedra, Derribador, Tremor y Marea de maná"
L["Enhancement and Restoration, once you have Water Shield: remind you to refresh it out of combat when under 1 minute, and recast it in combat when it drops"] = "Mejora y Recuperación, cuando tienes Escudo de agua: te recuerda renovarlo fuera de combate cuando le queda menos de 1 minuto, y volver a lanzarlo en combate cuando desaparece"
L["Restoration: suggest Chain Heal when at least this many group members are below 80% health. In combat Forever hides group health: LazyGCore estimates it from the damage and heals they take"] = "Recuperación: sugiere Curación en cadena cuando al menos este número de miembros del grupo está por debajo del 80% de salud. En combate Forever oculta la salud del grupo: LazyGCore la estima a partir del daño y la sanación que reciben"
L["Suggest Life Tap when you run low on mana and your health is above 50%. Between pulls it also reminds you below 60% mana when your health is above 75%"] = "Sugiere Transfusión de vida cuando te quedas sin maná y tu salud está por encima del 50%. Entre pulls también te lo recuerda por debajo del 60% de maná si tu salud está por encima del 75%"
L["Suggest Life Tap when mana is below this % (health above 50%). Forever hides your mana in combat, so there Life Tap is suggested once you can't afford Shadow Bolt. Between pulls a separate reminder appears below 60% mana"] = "Sugiere Transfusión de vida cuando el maná está por debajo de este % (salud por encima del 50%). Forever oculta tu maná en combate, así que allí se sugiere Transfusión de vida cuando ya no puedes pagar Descarga de las Sombras. Entre pulls aparece un recordatorio aparte por debajo del 60% de maná"
L["Solo, in combat: suggest Health Funnel when your demon drops below this % and your own health is above 55%. Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your demon takes. Needs Suggest defensives on (Combat page)"] = "En solitario, en combate: sugiere Cauce de salud cuando tu demonio baja de este % y tu propia salud está por encima del 55%. Forever oculta la salud de la mascota en combate: LazyGCore la estima a partir del daño y la sanación que recibe tu demonio. Requiere Sugerir defensivas activado (página Combate)"
L["Your one Curse per target. Auto: Curse of the Elements on elites and in groups (Curse of Weakness on elites before you learn it); on players Curse of Tongues for casters, Curse of Exhaustion or Weakness for the rest. A fixed curse goes on elites, group targets and players; None leaves the Curse to another Warlock (Banes still apply)"] = "Tu única maldición por objetivo. Auto: Maldición de los Elementos en élites y en grupo (Maldición de debilidad en élites antes de aprenderla); contra jugadores, Maldición de la lengua para lanzadores y Maldición de agotamiento o de debilidad para el resto. Una maldición fija se aplica en élites, objetivos de grupo y jugadores; Ninguna deja la maldición a otro brujo (los Terrores se siguen aplicando)"
L["Destruction only. Also picks your weapon stone (Firestone with Incinerate, Spellstone with Shadow Bolt) and the demon you sacrifice (Sayaad or Imp). Auto: Incinerate if you have the Incinerate talent and 5 points in Shadow and Flame, otherwise Shadow Bolt"] = "Solo Destrucción. También elige tu piedra para el arma (Piedra de fuego con Incinerar, Piedra de hechizos con Descarga de las Sombras) y el demonio que sacrificas (sayaad o diablillo). Auto: Incinerar si tienes el talento Incinerar y 5 puntos en Sombras y llamas; si no, Descarga de las Sombras"
L["Protection: build Sunder Armor to this many stacks on elites and in dungeons and raids, and refresh it before it drops (normal mobs while questing get 2)"] = "Protección: acumula Hender armadura hasta este número de acumulaciones en élites y en mazmorras y bandas, y renuévalo antes de que caiga (los enemigos normales en misiones reciben 2)"
L["Use Heroic Strike when rage is above this (Auto = per spec: 30 leveling, 60 Arms/Fury, 45 Protection). In combat Rage is hidden: LazyGCore checks you could still afford a spell of that cost (30+: Mortal Strike / Bloodthirst, 25: Intimidating Shout / Whirlwind, 20: Cleave / Thunder Clap, 15 or less: Heroic Strike)"] = "Usa Golpe heroico cuando la ira supera este valor (Auto = según especialización: 30 subida de nivel, 60 Armas/Furia, 45 Protección). En combate la ira está oculta: LazyGCore comprueba que aún podrías pagar un hechizo de ese coste (30+: Golpe mortal / Sed de sangre, 25: Grito intimidador / Huracán, 20: Mellar / Trueno, 15 o menos: Golpe heroico)"
L["Protection: on suggests Shield Block whenever you are tanking in melee. Off: only against elites or when your health is below 50%"] = "Protección: activado sugiere Bloquear con escudo siempre que estés tanqueando cuerpo a cuerpo. Desactivado: solo contra élites o cuando tu salud está por debajo del 50%"
L["Suggest Battle Shout whenever it is missing (out of combat also when under 10 seconds remain)"] = "Sugiere Grito de guerra siempre que falte (fuera de combate también cuando quedan menos de 10 segundos)"

-- sim pass: raid-only utility options
L["Faerie Fire in raids"] = "Fuego feérico en bandas"
L["Balance: keep Faerie Fire's armor debuff on the boss in raids. It only helps physical attackers and costs you a GCD and mana, so leave it off unless your raid has no other armor debuff. Groups of 5 always get it"] = "Equilibrio: mantiene el debuff de armadura de Fuego feérico en el jefe en bandas. Solo ayuda a los atacantes físicos y te cuesta un tiempo de reutilización global y maná, así que déjalo desactivado salvo que tu banda no tenga otro debuff de armadura. En grupos de 5 siempre se sugiere"
L["Vampiric Embrace in raids"] = "Unirse a vampírica en bandas"
L["Shadow: keep Vampiric Embrace on the boss in raids so your Shadow damage heals your party. It does no damage and costs a GCD every 30 seconds. In groups of 5 and in battlegrounds it is always suggested; solo only while your health is below 60%"] = "Sombra: mantiene Unirse a vampírica en el jefe en bandas para que tu daño de Sombras sane a tu grupo. No hace daño y cuesta un tiempo de reutilización global cada 30 segundos. En grupos de 5 y en campos de batalla siempre se sugiere; en solitario solo mientras tu salud esté por debajo del 60%"
L["Shows the colored ring around the main icon. The ring is also the swing timer, so hiding it also hides that swing timer (the swing timer bars stay visible)."] = "Muestra el anillo de color alrededor del icono principal. El anillo es también el temporizador de golpe: al ocultarlo también se oculta ese temporizador (las barras del temporizador de golpe siguen visibles)."
L["Hide/show the spell name, reason and DPS strip (and the queue in the stacked layout)"] = "Ocultar/mostrar el nombre del hechizo, el motivo y la barra de DPS (y la cola en el diseño apilado)"

