-- fix_talentrange: gear score label (GS) and auto attack reasons
L["Show your gear score (GS) under the keybind on the rotation icon. GS rates your equipped gear by item level and quality; the colour is its tier (green, blue, purple). Only shown at level 60."] = "Muestra tu GearScore (GS) bajo el atajo de teclado en el icono de rotación. El GS valora tu equipo puesto por nivel de objeto y calidad; el color indica su categoría (verde, azul, morado). Solo se muestra a nivel 60."
L["GS"] = "GS"
L["No wand and nothing to cast: melee."] = "Sin varita y nada que lanzar: cuerpo a cuerpo."
L["Start auto attack while energy builds."] = "Inicia el ataque automático mientras se acumula energía."
L["Closing in - start swinging when it reaches you."] = "Acercándote: empieza a golpear cuando te alcance."

-- fix_macros: per-character class macros, Account section, move to character
L["Account (all characters)"] = "Cuenta (todos los personajes)"
L["Will be saved to General (account) macros"] = "Se guardará en las macros generales (cuenta)"
L["Will be saved to Character macros"] = "Se guardará en las macros del personaje"
L["All your characters see this copy. Move it to keep it on this character only."] = "Todos tus personajes ven esta copia. Muévela para tenerla solo en este personaje."
L["Move to this character"] = "Mover a este personaje"
L["Moves this macro from the General (account) macros to this character's macros. Other characters lose this macro; put it back on your action bar."] = "Mueve esta macro de las macros generales (cuenta) a las macros de este personaje. Los demás personajes pierden esta macro; vuelve a ponerla en tu barra de acción."
L["(account macro)"] = "(macro de cuenta)"
L["%s moved to this character's macros. Put it back on your action bar."] = "%s se movió a las macros de este personaje. Vuelve a ponerla en tu barra de acción."
L["Could not move %s; nothing was deleted."] = "No se pudo mover %s; no se ha borrado nada."
L["Your General (account) macros are full (%d). Delete one in the macro window (/macro) first."] = "Tus macros generales (cuenta) están llenas (%d). Borra una antes en la ventana de macros (/macro)."
L["Your character macros are full (%d). Delete one in the macro window (/macro) first."] = "Tus macros del personaje están llenas (%d). Borra una antes en la ventana de macros (/macro)."
L["Use your top trinket (slot 13)"] = "Usa tu abalorio superior (ranura 13)"
L["Use your bottom trinket (slot 14)"] = "Usa tu abalorio inferior (ranura 14)"
L["Focus your mouseover, else your target"] = "Pon como foco el objetivo bajo el ratón; si no, tu objetivo"
L["Clear your focus"] = "Borra tu foco"
L["Target what your focus is targeting"] = "Selecciona el objetivo de tu foco"
L["Put a Skull on your target (press again to remove it)"] = "Pon una calavera en tu objetivo (pulsa otra vez para quitarla)"
L["Start a ready check (group leader or raid assistant)"] = "Inicia una comprobación de listos (líder de grupo o ayudante de banda)"
L["Show or hide the LazyGCore rotation display"] = "Muestra u oculta el panel de rotación de LazyGCore"
L["Reload the user interface"] = "Recarga la interfaz"


-- Growth features (Group Sync, share build, welcome tour, version notice)
L["A newer LazyGCore is out (%s) - update on CurseForge."] = "Hay una versión más reciente de LazyGCore (%s): actualízala en CurseForge."
L["Group Sync is off (Combat settings)."] = "La sincronización de grupo está desactivada (ajustes de Combate)."
L["You are not in a group."] = "No estás en un grupo."
L["No other LazyGCore users in your group yet."] = "Todavía no hay otros usuarios de LazyGCore en tu grupo."
L["LazyGCore users in your group"] = "Usuarios de LazyGCore en tu grupo"
L["newer"] = "más reciente"
L["List the LazyGCore users in your group and their versions"] = "Lista los usuarios de LazyGCore de tu grupo y sus versiones"
L["Group Sync"] = "Sincronización de grupo"
L["LazyGCore users in your party or raid quietly share their addon version, interrupt and big cooldowns over the hidden addon channel: the KICK! box shows who kicks next, and group cooldowns show under the display. Nothing is posted to chat and players without LazyGCore see nothing. Never sent while the game restricts addon messages (boss encounters, PvP)."] = "Los usuarios de LazyGCore de tu grupo o banda comparten en silencio, por el canal oculto de addons, su versión del addon, su interrupción y sus grandes tiempos de reutilización: el recuadro ¡CORTA! indica quién interrumpe a continuación y los tiempos del grupo aparecen bajo la pantalla. No se publica nada en el chat y los jugadores sin LazyGCore no ven nada. Nunca se envía mientras el juego restringe los mensajes de addons (encuentros con jefes, JcJ)."
L["Show group cooldowns"] = "Mostrar tiempos del grupo"
L["Shows a small line under the display when a LazyGCore user in your group uses a big defensive or raid cooldown (Shield Wall, Divine Shield, Innervate, Mana Tide Totem...). Hidden when you are solo. Only applies when Group Sync is on."] = "Muestra una pequeña línea bajo la pantalla cuando un usuario de LazyGCore de tu grupo usa un gran tiempo de reutilización defensivo o de banda (Muro de escudo, Escudo divino, Enervar, Tótem de marea de maná...). Oculta cuando juegas solo. Solo se aplica si la sincronización de grupo está activada."
L["New version notice"] = "Aviso de nueva versión"
L["Prints one line in your own chat window, once per session, when a group member runs a newer LazyGCore. Nobody else sees it."] = "Muestra una línea en tu propia ventana de chat, una vez por sesión, cuando un miembro del grupo usa una versión más reciente de LazyGCore. Nadie más la ve."
L["You kick next"] = "Interrumpes tú"
L["%s kicks next"] = "Interrumpe %s"
L["The welcome tour opens after combat."] = "La guía de bienvenida se abrirá después del combate."
L["Replay the short welcome tour"] = "Repite la breve guía de bienvenida"
L["Welcome"] = "Bienvenida"
L["Your rotation display"] = "Tu pantalla de rotación"
L["/lazygcore"] = "/lazygcore"
L["This is LazyGCore's display: the big icon is the ability to use next, PREV shows your last casts and NEXT what comes after. A grey icon is out of range or short on mana, the small icon beside it is a cooldown ready to use, and the LazyGCore logo means nothing to press. It shows in combat and when you target an enemy. Drag it to move it."] = "Esta es la pantalla de LazyGCore: el icono grande es la habilidad que debes usar a continuación, ANT muestra tus últimos lanzamientos y SIG lo que viene después. Un icono gris está fuera de alcance o te falta maná, el icono pequeño a su lado es un tiempo de reutilización listo para usar y el logo de LazyGCore significa que no hay nada que pulsar. Aparece en combate y cuando seleccionas a un enemigo. Arrástrala para moverla."
L["The Talents page shows the next talent of your build and lets you pick another build. While the talent frame is open, your next talent glows."] = "La página Talentos muestra el siguiente talento de tu build y te permite elegir otra build. Mientras la ventana de talentos está abierta, tu siguiente talento brilla."
L["Skip tour"] = "Saltar guía"
L["Next"] = "Siguiente"
L["Goes to the next step of the tour."] = "Pasa al siguiente paso de la guía."
L["Done"] = "Hecho"
L["Step %d of %d"] = "Paso %d de %d"
L["Enjoying LazyGCore? A rating on CurseForge helps other players find it."] = "¿Te gusta LazyGCore? Una valoración en CurseForge ayuda a otros jugadores a encontrarlo."
L["Click the link, then press Ctrl+C to copy it."] = "Haz clic en el enlace y pulsa Ctrl+C para copiarlo."
L["CurseForge"] = "CurseForge"
L["Say"] = "Decir"
L["Party"] = "Grupo"
L["Raid"] = "Banda"
L["Guild"] = "Hermandad"
L["Whisper target"] = "Susurrar al objetivo"
L["Whisper"] = "Susurrar a"
L["no player targeted"] = "ningún jugador seleccionado"
L["leveling build"] = "build de subida de nivel"
L["PvE build"] = "build JcE"
L["PvP build"] = "build JcJ"
L["You are not in a raid."] = "No estás en una banda."
L["You are not in a guild."] = "No estás en una hermandad."
L["Target a player to whisper your build."] = "Selecciona a un jugador para susurrarle tu build."
L["Chat is restricted right now. Try again after the fight."] = "El chat está restringido ahora mismo. Inténtalo después del combate."
L["Wait a few seconds before sharing again."] = "Espera unos segundos antes de volver a compartir."
L["Could not post the build."] = "No se pudo publicar la build."
L["No talent build to share for this spec."] = "No hay build de talentos que compartir para esta especialización."
L["Posts to: %s"] = "Se publica en: %s"
L["Share build"] = "Compartir build"
L["Post to"] = "Publicar en"
L["Where Share build posts your build: Say, Party, Raid, Guild, or a whisper to the player you target."] = "Dónde publica tu build Compartir build: Decir, Grupo, Banda, Hermandad o un susurro al jugador que tengas seleccionado."

