-- Share LazyGCore tab, chat channels, contact links, welcome tour (UI/ShareLazyGCore, UI/Welcome)
L["Other LazyGCore users: %d in your group, %d in your guild"] = "Otros usuarios de LazyGCore: %d en tu grupo, %d en tu hermandad"
L["Turn on Share gear score with LazyGCore users (Parsing tab) to see how many players around you use LazyGCore."] = "Activa Compartir la puntuación de equipo con usuarios de LazyGCore (pestaña Análisis) para ver cuántos jugadores a tu alrededor usan LazyGCore."
L["Follow LazyGCore"] = "Sigue a LazyGCore"
L["Enjoying LazyGCore? Follow it and add it to your favorites on CurseForge: you hear about every update first, and it helps other players find it."] = "¿Te gusta LazyGCore? Síguelo y añádelo a tus favoritos en CurseForge: te enterarás antes que nadie de cada actualización y ayudarás a otros jugadores a encontrarlo."
L["Share LazyGCore"] = "Compartir LazyGCore"
L["Know someone who would like LazyGCore? Share it in one click. When your group runs LazyGCore together, Group Sync shows who kicks next."] = "¿Conoces a alguien a quien le gustaría LazyGCore? Compártelo con un clic. Si tu grupo usa LazyGCore, la sincronización de grupo muestra quién interrumpe a continuación."
L["I use LazyGCore Forever for my rotation and talents: it shows what to press next. Free on CurseForge: %s - get it too and Group Sync shows who kicks next!"] = "Uso LazyGCore Forever para mi rotación y talentos: te dice qué pulsar a continuación. Gratis en CurseForge: %s - ¡consíguelo tú también y la sincronización de grupo mostrará quién interrumpe!"
L["Posts ONE chat line telling your friends about LazyGCore Forever, with the CurseForge link, to the channel picked in Post to. Sent only when you click, never automatically."] = "Publica UNA línea de chat que presenta LazyGCore Forever a tus amigos, con el enlace de CurseForge, en el canal elegido en Publicar en. Solo se envía cuando haces clic, nunca automáticamente."
L["Where Share LazyGCore and Share build post: Say, Party, Raid, Guild, a whisper to the player you target, or a chat channel you have joined (Trade, General, LookingForGroup ...). Public channels: one share a minute."] = "Dónde publican Compartir LazyGCore y Compartir build: Decir, Grupo, Banda, Hermandad, un susurro al jugador seleccionado o un canal de chat al que te hayas unido (Comercio, General, BuscarGrupo ...). Canales públicos: una vez por minuto."
L["Target a player to whisper the link."] = "Selecciona a un jugador para susurrarle el enlace."
L["Could not post the message."] = "No se pudo publicar el mensaje."
L["Usage: /lazygcore share [say / party / raid / guild / whisper / trade / general / channel number]"] = "Uso: /lazygcore share [say / party / raid / guild / whisper / trade / general / número de canal]"
L["Tell your friends about LazyGCore: posts one chat line (say, party, raid, guild, whisper or a chat channel such as trade)"] = "Cuéntales a tus amigos sobre LazyGCore: publica una línea de chat (decir, grupo, banda, hermandad, susurro o un canal de chat como Comercio)"
L["You can also type /lazygcore share, or /lazygcore share trade, general, guild, party ..."] = "También puedes escribir /lazygcore share, o /lazygcore share trade, general, guild, party ..."
L["Suggestions & bug reports"] = "Sugerencias e informes de errores"
L["Have an idea, or did LazyGCore suggest something wrong? Tell me on CurseForge: leave a comment on the LazyGCore page or message me on my profile. Include your class, spec and what /lazygcore status prints."] = "¿Tienes una idea o LazyGCore te sugirió algo incorrecto? Cuéntamelo en CurseForge: deja un comentario en la página de LazyGCore o escríbeme en mi perfil. Indica tu clase, especialización y lo que muestra /lazygcore status."
L["Comments"] = "Comentarios"
L["Comments on the LazyGCore Forever page. Click the link, then press Ctrl+C to copy it."] = "Comentarios en la página de LazyGCore Forever. Haz clic en el enlace y pulsa Ctrl+C para copiarlo."
L["The author's CurseForge profile. Click the link, then press Ctrl+C to copy it."] = "El perfil de CurseForge del autor. Haz clic en el enlace y pulsa Ctrl+C para copiarlo."
L["Welcome tour"] = "Guía de bienvenida"
L["A short tour of the display and every settings tab."] = "Un breve recorrido por el panel y cada pestaña de ajustes."
L["Replay The Welcome Tour"] = "Repetir la guía de bienvenida"
L["Shows the welcome tour again: the display and every settings tab, one step at a time."] = "Muestra de nuevo la guía de bienvenida: el panel y cada pestaña de ajustes, paso a paso."
L["not joined"] = "no unido"
L["You are not in the %s channel right now (Trade only works in cities)."] = "Ahora mismo no estás en el canal %s (Comercio solo funciona en ciudades)."
L["Public channels: one share a minute. Try again shortly."] = "Canales públicos: compartir una vez por minuto. Inténtalo de nuevo en breve."
L["Closes the tour. You can replay it from the Share LazyGCore tab or with /lazygcore tour."] = "Cierra la guía. Puedes repetirla desde la pestaña Compartir LazyGCore o con /lazygcore tour."
L["Goes back to the previous step of the tour."] = "Vuelve al paso anterior de la guía."
L["Turn LazyGCore on or off, lock the display, pick the rotation engine and spec, choose when the display shows, and change its theme, skin and size. Hover over any option to see what it does."] = "Activa o desactiva LazyGCore, bloquea el panel, elige el motor de recomendaciones y la especialización, decide cuándo se muestra el panel y cambia su tema, aspecto y tamaño. Pasa el ratón por cualquier opción para ver qué hace."
L["Everything on the display: the main and cooldown icons, spell history and timeline, the action bar glow and the swing timer."] = "Todo lo del panel: los iconos principal y de reutilización, el historial y la línea de tiempo de hechizos, el brillo de la barra de acción y el temporizador de golpes."
L["What LazyGCore suggests (AoE, defensives, buffs and pets), the KICK!, DEFENSIVE! and PURGE alerts with their sounds, and Group Sync with your group."] = "Lo que sugiere LazyGCore (AoE, defensivas, beneficios y mascotas), las alertas KICK!, DEFENSIVE! y PURGE con sus sonidos, y la sincronización con tu grupo."
L["Options for your own class, such as the Warlock curse, Rogue finishers or Mage mana gems."] = "Opciones para tu propia clase, como la maldición del brujo, los remates del pícaro o las gemas de maná del mago."
L["Ready-made macros for your class and spec (PvE and PvP), plus account macros for all your characters. One click creates them."] = "Macros listas para tu clase y especialización (JcE y JcJ), además de macros de cuenta para todos tus personajes. Un clic las crea."
L["Your DPS and HPS strip, the Stats window, GearScore, consumables, parse readiness and who else uses LazyGCore."] = "Tu barra de DPS y HPS, la ventana de estadísticas, GearScore, consumibles, preparación para parses y quién más usa LazyGCore."
L["Build your own rotation, exclude spells you never want suggested, and turn LazyGCore off in chosen instances."] = "Crea tu propia rotación, excluye hechizos que nunca quieras ver sugeridos y desactiva LazyGCore en las instancias que elijas."
L["Update speed, troubleshooting tools and Reset all settings."] = "Velocidad de actualización, herramientas de diagnóstico y Restablecer todos los ajustes."
L["Save, load, copy and share your settings, or switch profiles automatically per spec."] = "Guarda, carga, copia y comparte tus ajustes, o cambia de perfil automáticamente según la especialización."
L["LazyGCore speaks six languages: English, German, Spanish, French, Japanese and Simplified Chinese. Pick one here, or keep Auto."] = "LazyGCore habla seis idiomas: inglés, alemán, español, francés, japonés y chino simplificado. Elige uno aquí o deja Auto."
L["What LazyGCore is and how it reads the game on Forever."] = "Qué es LazyGCore y cómo lee el juego en Forever."
L["Type /lazygcore for the settings, /lazygcore help for every command. Replay this tour any time from the Share LazyGCore tab."] = "Escribe /lazygcore para los ajustes y /lazygcore help para todos los comandos. Repite esta guía cuando quieras desde la pestaña Compartir LazyGCore."

-- LazyGCore links (ShareLink)
L["%s Click it with LazyGCore Forever to use it - free on CurseForge: %s"] = "%s Haz clic con LazyGCore Forever para usarlo - gratis en CurseForge: %s"
L["%s %s rotation"] = "rotación de %s %s"
L["%s %s %s"] = "%s %s: %s"
L["Before %s's rotation"] = "Antes de la rotación de %s"
L["No rotation to share for this spec."] = "No hay ninguna rotación que compartir para esta especialización."
L["Share rotation"] = "Compartir rotación"
L["Posts a LazyGCore link to the build your Talent Guide follows, to the channel picked in Post to. Players with LazyGCore click it to follow the same build; everyone else sees where to get LazyGCore. Sent only when you click."] = "Publica un enlace de LazyGCore a la build que sigue tu guía de talentos, en el canal elegido en Publicar en. Quien tenga LazyGCore hace clic para seguir la misma build; los demás ven dónde conseguir LazyGCore. Solo se envía cuando haces clic."
L["Posts a LazyGCore link to your rotation for this spec (your custom list, or LazyGCore's default when you have none), to the channel picked in Post to. Players with LazyGCore click it to use it; everyone else sees where to get LazyGCore. Sent only when you click."] = "Publica un enlace de LazyGCore a tu rotación de esta especialización (tu lista personalizada, o la predeterminada de LazyGCore si no tienes), en el canal elegido en Publicar en. Quien tenga LazyGCore hace clic para usarla; los demás ven dónde conseguir LazyGCore. Solo se envía cuando haces clic."
L["That is your own share."] = "Es tu propio enlace compartido."
L["LazyGCore links open after combat."] = "Los enlaces de LazyGCore se abren después del combate."
L["LazyGCore can't send right now (combat, a boss fight or PvP). Try again in a moment."] = "LazyGCore no puede enviar ahora mismo (combate, jefe o JcJ). Inténtalo de nuevo en un momento."
L["Already asking for that share..."] = "Ya se está pidiendo ese enlace..."
L["That LazyGCore link doesn't work."] = "Ese enlace de LazyGCore no funciona."
L["Asking %s for their LazyGCore share..."] = "Pidiendo a %s su enlace de LazyGCore..."
L["%s didn't answer. They must be online, and a share lasts 2 hours (or until they reload)."] = "%s no respondió. Tiene que estar conectado, y un enlace dura 2 horas (o hasta que recargue)."
L["%s's share has expired. Ask them to share it again."] = "El enlace de %s ha caducado. Pídele que lo comparta de nuevo."
L["%s shared it for another class: it only works for that class."] = "%s lo compartió para otra clase: solo funciona con esa clase."
L["%s's share is for a spec LazyGCore doesn't know here."] = "El enlace de %s es para una especialización que LazyGCore no conoce aquí."
L["%s's build isn't in your LazyGCore version. Update LazyGCore and try again."] = "La build de %s no está en tu versión de LazyGCore. Actualiza LazyGCore e inténtalo de nuevo."
L["%s's rotation has nothing your LazyGCore can use."] = "La rotación de %s no tiene nada que tu LazyGCore pueda usar."
L["%s's share couldn't be read."] = "No se pudo leer el enlace de %s."
L["%s shared a %s rotation (%d spells: %s).\n\nUse it as your custom rotation? Your current list is kept as a saved rotation."] = "%s compartió una rotación de %s (%d hechizos: %s).\n\n¿Usarla como tu rotación personalizada? Tu lista actual se guarda como rotación guardada."
L["Using %s's %s rotation. Change it any time on the Competitive tab."] = "Usando la rotación de %s (%s). Cámbiala cuando quieras en la pestaña Competitivo."
L["Use it"] = "Usarla"
L["%s shared a %s build: %s.\n\nFollow it in your Talent Guide?"] = "%s compartió una build de %s: %s.\n\n¿Seguirla en tu guía de talentos?"
L["Your Talent Guide now follows %s's %s build."] = "Tu guía de talentos ahora sigue la build de %s (%s)."
L["Follow it"] = "Seguirla"
L["Share your rotation and build"] = "Comparte tu rotación y tu build"
L["Posts a LazyGCore link to the same channel. Players with LazyGCore click it to use your rotation or follow your talent build; everyone else sees where to get LazyGCore."] = "Publica un enlace de LazyGCore en el mismo canal. Quien tenga LazyGCore hace clic para usar tu rotación o seguir tu build de talentos; los demás ven dónde conseguir LazyGCore."
L["Scan with your phone to open LazyGCore Forever on CurseForge."] = "Escanéalo con tu móvil para abrir LazyGCore Forever en CurseForge."
L["Point your phone's camera at the code to open LazyGCore Forever on CurseForge."] = "Apunta la cámara de tu móvil al código para abrir LazyGCore Forever en CurseForge."
L["QR code"] = "Código QR"
L["Start here: share LazyGCore with friends in one click (party, guild, whisper or a channel like Trade), share your rotation or talent build as a LazyGCore link, send me suggestions or bug reports, and replay this tour."] = "Empieza aquí: comparte LazyGCore con tus amigos en un clic (grupo, hermandad, susurro o un canal como Comercio), comparte tu rotación o build de talentos como enlace de LazyGCore, envíame sugerencias o errores y repite esta guía."

LazyGCore.Locale:RegisterLocale("esES", L)

-- 1.0.7 (16 Oct beta build)
L["Arcane Wrath"] = "Cólera Arcana"
L["Presence of Mind: instant 3.5s Arcane Wrath."] = "Presencia mental: Cólera Arcana de 3,5 s instantánea."
L["Your hardest hit: scales with your maximum mana (6s cooldown)."] = "Tu golpe más fuerte: escala con tu maná máximo (6 s de reutilización)."
L["Winter's Chill: +40% Cone of Cold damage per stack."] = "Frío invernal: +40% de daño de Cono de frío por acumulación."
L["15s: faster Lightning Bolt and Lava Burst, Chain Lightning without a cooldown."] = "15 s: Descarga de relámpagos y Ráfaga de lava más rápidos, Cadena de relámpagos sin reutilización."
L["Elemental Mastery: no cooldown on Chain Lightning."] = "Maestría elemental: Cadena de relámpagos sin reutilización."

-- 1.0.7 (16 Oct beta build)
L["Nothing to press right now - keep attacking."] = "Nada que pulsar ahora mismo: sigue atacando."
L["Enemy nameplates are off, so LazyGCore can't count the enemies around you and won't suggest AoE spells. Press V or type /lazygcore nameplates to turn them on."] = "Las placas de nombre enemigas están desactivadas, así que LazyGCore no puede contar los enemigos a tu alrededor y no sugerirá hechizos de área. Pulsa V o escribe /lazygcore nameplates para activarlas."

-- 1.0.7 (16 Oct beta build)
L["Type /lazygcore reset confirm to reset all settings and reload the UI."] = "Escribe /lazygcore reset confirm para restablecer todos los ajustes y recargar la interfaz."

-- 1.0.7 (16 Oct beta build)
L["Use it on your weapon."] = "Úsala en tu arma."

-- 1.0.7 (16 Oct beta build)
L["Before Demonic Pact: Searing Pain out-damages Shadow Bolt."] = "Antes de Pacto demoníaco: Dolor abrasador hace más daño que Descarga de las Sombras."
L["Questing: free damage while you nuke."] = "En misiones: daño gratis mientras lanzas hechizos."

-- 1.0.7 (16 Oct beta build)
L["Can't change that in combat."] = "No se puede cambiar en combate."
L["Enemy nameplates are on: LazyGCore can count the enemies around you for AoE."] = "Las placas de nombre enemigas están activadas: LazyGCore puede contar los enemigos a tu alrededor para el daño de área."
L["Turn on enemy nameplates (LazyGCore counts nearby enemies from them for AoE suggestions)"] = "Activa las placas de nombre enemigas (LazyGCore cuenta con ellas los enemigos cercanos para las sugerencias de área)"
L["Automatic AoE threshold"] = "Umbral de área automático"
L["Uses the best number of enemies for your spec, worked out by simulation (for example 2 for cleave specs). Turn it off to set your own number below. Only applies when Enable AoE suggestions is on."] = "Usa el mejor número de enemigos para tu especialización, calculado por simulación (por ejemplo 2 para especializaciones de golpes en cadena). Desactívalo para fijar tu propio número abajo. Solo se aplica si Activar sugerencias AoE está activado."

-- 1.0.7 (16 Oct beta build)
L["Sunder Armor as DPS"] = "Hender armadura como DPS"
L["Arms and Fury: stack Sunder Armor to 5 against elites and in 5-player groups when nobody else applies it (a big damage gain). Leave it off when a tank or another warrior sunders. Never in raids"] = "Armas y Furia: acumula Hender armadura hasta 5 contra élites y en grupos de 5 cuando nadie más lo aplica (mucho más daño). Déjalo desactivado si un tanque u otro guerrero lo aplica. Nunca en bandas"
L["Nobody else sunders: armor shred is worth more than your next hit."] = "Nadie más aplica Hender: reducir la armadura vale más que tu próximo golpe."

-- 1.0.7 (16 Oct beta build)
L["Improved Scorch: fast crits feed Heating Up."] = "Chamuscar mejorado: los críticos rápidos alimentan Calentamiento."

-- 1.0.7 (16 Oct beta build)
L["Group: instant, shares Aimed Shot's cooldown."] = "Grupo: instantáneo, comparte la reutilización de Tiro de puntería."

-- 1.0.8
L["Rotation for"] = "Rotación para"
L["Automatic"] = "Automático"
L["Open world"] = "Mundo abierto"
L["Dungeon"] = "Mazmorra"
L["Usage: /lazygcore content auto | world | dungeon | raid"] = "Uso: /lazygcore content auto | world | dungeon | raid"
L["Show or set the content the rotation is for: auto, world (questing), dungeon or raid"] = "Muestra o fija para qué contenido es la rotación: auto, world (misiones), dungeon o raid"
L["Which rotation to use (this character). Automatic: the open-world questing rotation outside instances, also when you quest in a party, the dungeon rotation in 5-player dungeons and the raid rotation in raids. Pick one to always use it. Also /lazygcore content."] = "Qué rotación usar (este personaje). Automático: la rotación de misiones del mundo abierto fuera de las instancias, también cuando haces misiones en grupo, la rotación de mazmorra en mazmorras de 5 jugadores y la de banda en bandas. Elige una para usarla siempre. También /lazygcore content."

-- 1.0.8
L["Out of mana: drink a mana potion."] = "Sin maná: bebe una poción de maná."
L["Low health: drink a healing potion."] = "Poca salud: bebe una poción de sanación."
L["Potions"] = "Pociones"
L["Shows a mana potion on the cooldown icon once a fight has run you out of mana, and a healing potion below 35% health (the best potion in your bags, when its cooldown is ready)."] = "Muestra una poción de maná en el icono de reutilización cuando un combate te ha dejado sin maná, y una poción de sanación por debajo del 35% de salud (la mejor poción de tus bolsas, cuando su reutilización está lista)."
L["Your pet is not happy: feed it for full damage."] = "Tu mascota no está contenta: dale de comer para que haga todo su daño."

-- 1.0.8
L["Feed Pet"] = "Alimentar mascota"

-- 1.0.9
L["Playstyle"] = "Estilo de juego"
L["Efficient"] = "Eficiente"
L["Balanced"] = "Equilibrado"
L["Max damage"] = "Daño máximo"
L["Questing solo"] = "Misiones en solitario"
L["Questing in a group"] = "Misiones en grupo"
L["Usage: /lazygcore style auto | efficient | balanced | max"] = "Uso: /lazygcore style auto | efficient | balanced | max"
L["Show or set the playstyle: auto, efficient (save mana and health), balanced or max (most damage)"] = "Muestra o fija el estilo de juego: auto, efficient (ahorra maná y salud), balanced o max (máximo daño)"
L["How hard to push (this character). Efficient: saves mana and health - fewer breaks to drink and eat while questing, more mana left after each pull in groups. Balanced: the fastest leveling counting rest, and steady damage with a mana reserve in groups. Max damage: the most damage now - every mob dies as fast as possible, best for raid bosses and when a healer keeps you up. Automatic: Balanced while questing and in dungeons, Max damage in raids and PvP. Where the simulator found nothing better for your spec, two styles play the same. Also /lazygcore style."] = "Cuánto presionar (este personaje). Eficiente: ahorra maná y salud - menos pausas para beber y comer al hacer misiones, más maná tras cada grupo de enemigos en grupo. Equilibrado: la subida de nivel más rápida contando el descanso, y daño constante con reserva de maná en grupo. Daño máximo: el mayor daño ahora - cada enemigo muere lo antes posible, ideal para jefes de banda y cuando un sanador te mantiene. Automático: Equilibrado en misiones y mazmorras, Daño máximo en bandas y JcJ. Donde el simulador no encontró nada mejor para tu especialización, dos estilos juegan igual. También /lazygcore style."
L["Cheap nuke: more damage per mana here than the DoTs."] = "Ataque barato: aquí más daño por maná que los DoT."
