-- 1.1.0 (launch changes)
L["Dungeons"] = "Mazmorras"
L["Raids"] = "Bandas"
L["LazyGCore's picks"] = "Recomendaciones de LazyGCore"
L["LazyGCore's pick for:"] = "Recomendado por LazyGCore para:"
L["Click to follow this build."] = "Haz clic para seguir esta configuración."
L["Arms: a two-hander with Sweeping Strikes and Mortal Strike kills fast, and Improved Tactical Mastery keeps your Rage on stance swaps."] = "Armas: un arma de dos manos con Golpes de barrido y Golpe mortal mata rápido, y Maestría táctica mejorada conserva tu ira al cambiar de actitud."
L["Groups need tanks: Protection holds packs with Thunder Clap, Shield Slam and Revenge. Go Fury if you join as damage."] = "Los grupos necesitan tanques: Protección aguanta grupos con Atronar, Embate con escudo y Revancha. Elige Furia si vas como daño."
L["Fury: two weapons with Bloodthirst, Flurry and Whirlwind for the most boss damage. Raid tanks stay Protection."] = "Furia: dos armas con Sed de sangre, Ráfaga y Torbellino para el mayor daño a jefes. Los tanques de banda siguen en Protección."
L["Arms: Mortal Strike halves the healing your target takes - the warrior pick for battlegrounds and duels."] = "Armas: Golpe mortal reduce a la mitad la sanación que recibe tu objetivo; la opción del guerrero para campos de batalla y duelos."
L["Retribution: Seal of Command and Unsealed Wrath hit hard, and you heal yourself instead of resting."] = "Reprensión: Sello de orden y Unsealed Wrath golpean fuerte, y te sanas tú mismo en vez de descansar."
L["Protection: Consecration and Holy Shield hold whole packs. Holy if your group needs a healer."] = "Protección: Consagración y Escudo Sagrado aguantan grupos enteros. Sagrado si tu grupo necesita sanador."
L["Holy: big, mana-efficient heals on the tanks with Holy Shock and Light's Vigil."] = "Sagrado: sanaciones grandes y eficientes en maná sobre los tanques con Choque Sagrado y Light's Vigil."
L["Retribution: Seal of Command bursts and Repentance controls. Holy if you want to heal in battlegrounds."] = "Reprensión: Sello de orden para ráfagas y Arrepentimiento para controlar. Sagrado si quieres sanar en campos de batalla."
L["Beast Mastery: your pet tanks and Bestial Wrath kills fast - the easiest way to level."] = "Dominio de bestias: tu mascota tanquea y Cólera de las bestias mata rápido; la forma más fácil de subir de nivel."
L["Marksmanship: steady ranged damage, Trueshot Aura for the group and Barrage on packs."] = "Puntería: daño a distancia constante, Aura de disparo certero para el grupo y Tromba contra grupos."
L["Marksmanship: the strongest sustained ranged damage, and Trueshot Aura helps the raid."] = "Puntería: el daño a distancia sostenido más fuerte, y Aura de disparo certero ayuda a la banda."
L["Survival: Counterattack, Deterrence and Entrapment keep melee off you."] = "Supervivencia: Contraataque, Disuasión y Atrapar mantienen alejados a los cuerpo a cuerpo."
L["Combat: Sinister Strike, Shank and Adrenaline Rush with any weapon - fast kills, few deaths."] = "Combate: Golpe siniestro, Shank y Subidón de adrenalina con cualquier arma; muertes rápidas y pocas derrotas."
L["Combat: Blade Flurry is the best rogue damage on packs."] = "Combate: Aluvión de acero es el mejor daño de pícaro contra grupos."
L["Assassination: Mutilate and the stronger launch poisons for steady boss damage."] = "Asesinato: Mutilar y los venenos más fuertes del lanzamiento para un daño constante a jefes."
L["Subtlety: Premeditation, Preparation and Death Mark for the hardest openers."] = "Sutileza: Premeditación, Preparación y Marca de muerte para las aperturas más duras."
L["Shadow: Spirit Tap, DoTs and Mind Flay - very little drinking between fights."] = "Sombra: Aprovechar espíritu, DoTs y Tortura mental; casi no hay que beber entre combates."
L["Holy: Prayer of Healing and Holy Nova keep a whole group up. Discipline works too."] = "Sagrado: Rezo de sanación y Nova Sagrada mantienen vivo a todo el grupo. Disciplina también sirve."
L["Holy: the strongest group and raid healing."] = "Sagrado: la sanación de grupo y de banda más fuerte."
L["Discipline: Penance, strong shields and Power Infusion. Shadow if you want damage."] = "Disciplina: Penitencia, escudos fuertes e Infusión de poder. Sombra si quieres daño."
L["Enhancement: Stormstrike every 8 seconds with Flurry and Windfury, and you heal yourself between pulls."] = "Mejora: Ataque de tormenta cada 8 segundos con Ráfaga y Viento furioso, y te sanas entre combates."
L["Restoration: Chain Heal and totems - groups always look for one."] = "Restauración: Sanación en cadena y tótems; los grupos siempre buscan uno."
L["Restoration: Chain Heal and Mana Tide Totem, the shaman role raids want most."] = "Restauración: Sanación en cadena y Tótem Marea de maná, el rol de chamán que más buscan las bandas."
L["Elemental: the stronger launch shocks give big burst. Restoration if you heal."] = "Elemental: los choques más fuertes del lanzamiento dan gran ráfaga. Restauración si sanas."
L["Frost: slows and Frost Nova keep mobs off you; this build pulls whole packs from about 30."] = "Escarcha: las ralentizaciones y Nova de Escarcha mantienen alejados a los enemigos; esta configuración atrae grupos enteros desde el nivel 30 aprox."
L["Frost: Blizzard and Cone of Cold on packs, and control when a pull goes wrong."] = "Escarcha: Ventisca y Cono de frío contra grupos, y control cuando un combate sale mal."
L["Fire: Ignite and Combustion for the most boss damage."] = "Fuego: Ignición y Combustión para el mayor daño a jefes."
L["Frost: Shatter combos, Ice Block and Ice Barrier."] = "Escarcha: combos de Hacer añicos, Bloque de hielo y Barrera de hielo."
L["Affliction: DoTs and drains keep you topped up - almost no downtime."] = "Aflicción: DoTs y drenajes te mantienen al máximo; casi sin pausas."
L["Destruction: Shadow Bolt and Incinerate damage, Rain of Fire on packs."] = "Destrucción: daño de Descarga de las Sombras e Incinerar, Lluvia de fuego contra grupos."
L["Destruction: the most single-target damage."] = "Destrucción: el mayor daño a un solo objetivo."
L["Affliction: DoTs, fears and drains wear players down."] = "Aflicción: DoTs, miedos y drenajes desgastan a los jugadores."
L["Feral: Cat Form kills fast, Bear Form saves bad pulls, Travel Form between quests."] = "Combate feral: la forma felina mata rápido, la forma de oso salva malos combates y la forma de viaje entre misiones."
L["Feral Bear: tanks packs with Swipe and Lacerate. Restoration if you heal."] = "Oso feral: tanquea grupos con Flagelo y Lacerar. Restauración si sanas."
L["Restoration: HoTs, Wild Growth and Swiftmend - raids always want druid healers."] = "Restauración: HoTs, Crecimiento salvaje y Alivio presto; las bandas siempre quieren druidas sanadores."
L["Feral: shift out of roots and snares. Restoration is a strong battleground healer."] = "Combate feral: cambia de forma para librarte de raíces y ralentizaciones. Restauración es un gran sanador en campos de batalla."
-- 1.1.0 (launch changes)
L["following"] = "siguiendo"
L["click to follow"] = "clic para seguir"
L["Not sure which build to take? Click the one for what you play next."] = "¿No sabes qué configuración elegir? Haz clic en la de lo que vas a jugar."
-- 1.1.0 (launch changes)
L["The Talents page shows the next talent of your build and lets you pick another build. LazyGCore's picks tell you the best build for leveling, dungeons, raids and PvP - one click to follow. While the talent frame is open, your next talent glows."] = "La página de talentos muestra el siguiente talento de tu configuración y te deja elegir otra. Las recomendaciones de LazyGCore te dicen la mejor configuración para subir de nivel, mazmorras, bandas y JcJ: un clic para seguirla. Mientras la ventana de talentos está abierta, tu siguiente talento brilla."
-- 1.1.0 (launch changes)
L["I use LazyGCore Forever: it shows what to press next, the best talent build for leveling, dungeons, raids and PvP, and ready-made macros. Free on CurseForge: %s"] = "Uso LazyGCore Forever: muestra qué pulsar a continuación, la mejor configuración de talentos para subir de nivel, mazmorras, bandas y JcJ, y macros listas. Gratis en CurseForge: %s"
L["Know someone who would like LazyGCore? Share it in one click: what to press next, the best talents for leveling, dungeons, raids and PvP, and ready-made macros."] = "¿Conoces a alguien a quien le gustaría LazyGCore? Compártelo con un clic: qué pulsar a continuación, los mejores talentos para subir de nivel, mazmorras, bandas y JcJ, y macros listas."
-- 1.1.0 (launch changes)
L["LazyGCore links open after the boss fight."] = "Los enlaces de LazyGCore se abren después del combate contra el jefe."
L["LazyGCore links don't work inside battlegrounds and arenas."] = "Los enlaces de LazyGCore no funcionan en campos de batalla ni arenas."
L["The game is blocking addon messages right now. Try again in a moment."] = "El juego está bloqueando los mensajes de addons ahora mismo. Inténtalo de nuevo en un momento."
L["That player is offline, so their share can't be fetched."] = "Ese jugador está desconectado, así que no se puede obtener lo que compartió."
L["Too many messages at once. Try again in a few seconds."] = "Demasiados mensajes a la vez. Inténtalo de nuevo en unos segundos."
L["The game didn't send the request. Try again in a moment."] = "El juego no envió la solicitud. Inténtalo de nuevo en un momento."
-- 1.1.0 (launch changes)
L["Tip:"] = "Consejo:"
L["Dual Wield Specialization needs a weapon in your off hand."] = "Especialización en doble empuñadura necesita un arma en la mano izquierda."
L["Two-Handed Weapon Specialization only works with a two-handed weapon."] = "Especialización en armas de dos manos solo funciona con un arma de dos manos."
L["Your Protection talents (Bastion, Shield Slam, Defiance) need a shield."] = "Tus talentos de Protección (Bastion, Embate con escudo, Desafío) necesitan un escudo."
L["Weaponmaster gives no bonus with daggers or fist weapons."] = "Maestro de armas no da bonificación con dagas ni armas de puño."
L["Holy Shield and your Protection talents need a shield."] = "Escudo Sagrado y tus talentos de Protección necesitan un escudo."
L["Mutilate needs a dagger in each hand."] = "Mutilar necesita una daga en cada mano."
L["Hemorrhage and Ghostly Strike hit much harder with a dagger in your main hand."] = "Hemorragia y Golpe fantasmal golpean mucho más fuerte con una daga en la mano derecha."
L["Weapon tips"] = "Consejos de armas"
L["Out of combat, a soft tip when your weapons don't suit your talents: a two-hander for Two-Handed Weapon Specialization, a shield for Protection, an off-hand weapon for Dual Wield Specialization, daggers for Mutilate. Also one chat line when you equip them. Never during a fight."] = "Fuera de combate, un consejo suave cuando tus armas no encajan con tus talentos: un arma de dos manos para Especialización en armas de dos manos, un escudo para Protección, un arma en la mano izquierda para Especialización en doble empuñadura, dagas para Mutilar. También una línea en el chat al equiparlas. Nunca durante un combate."
-- 1.1.0 (launch changes)
L["CD"] = "CD"
L["BUFF"] = "BUFF"
-- 1.1.0 (launch changes)
L["Damage trinket: use it with your cooldowns."] = "Abalorio de daño: úsalo junto con tus reutilizaciones."
L["Shows a ready damage trinket in the cooldown slot in fights worth it (elites, dungeons and raids, players, 3+ enemies) - only trinkets whose use effect adds damage for your spec, never defensive or utility ones. Also your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "Muestra un abalorio de daño listo en la casilla de reutilización en combates que lo merecen (élites, mazmorras y bandas, jugadores, 3+ enemigos): solo abalorios cuyo efecto de uso añade daño para tu especialización, nunca defensivos ni de utilidad. También tu abalorio JcJ cuando estás aturdido o asustado (con Sugerir defensivas activado)."
-- 1.1.0 (launch changes)
L["Your swings stored this Seal: swap now, the next hit fires the copies."] = "Tus golpes guardaron este Sello: cámbialo ya, el siguiente golpe activa las copias."
-- 1.1.0 (launch changes)
L["Fury: two one-handers with Bloodthirst, Whirlwind and Flurry kill fastest while leveling. Arms before you can dual wield (20)."] = "Furia: dos armas de una mano con Sed de sangre, Torbellino y Ráfaga matan más rápido al subir de nivel. Armas hasta que puedas usar dos armas (20)."
-- 1.1.0 (launch changes)
L["Arcane: Arcane Blast stacks with Arcane Power and Presence of Mind - the most boss damage, and mana that lasts the whole fight."] = "Arcano: cargas de Explosión Arcana con Poder Arcano y Presencia mental: el mayor daño a jefes y maná para todo el combate."
-- 1.1.0 (launch changes)
L["Auto: each spec's own choice (Subtlety: Rupture on elites, groups and players; Assassination, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "Auto: la elección de cada especialización (Sutileza: Ruptura en élites, grupos y jugadores; Asesinato, Combate y subida de nivel: solo Eviscerar). Ruptura: primero Ruptura siempre que falte en un objetivo con más del 35% de salud. Eviscerar: nunca Ruptura"
-- 1.1.0 (launch changes)
L["Show spells on cooldown"] = "Mostrar hechizos en reutilización"
L["In combat, when nothing is ready, the main icon shows the next spell that comes off cooldown, greyed out with its cooldown. Off: only spells you can press right now are shown."] = "En combate, cuando no hay nada listo, el icono principal muestra el siguiente hechizo que sale de reutilización, en gris y con su tiempo de reutilización. Desactivado: solo se muestran los hechizos que puedes pulsar ahora."
L["'Nothing to press' in combat"] = "'Nada que pulsar' en combate"
L["In combat, when there is nothing to press right now, the main icon shows the LazyGCore logo and 'Nothing to press right now - keep attacking.' Off: the icon and the text stay empty instead."] = "En combate, cuando no hay nada que pulsar en ese momento, el icono principal muestra el logo de LazyGCore y 'Nada que pulsar ahora - sigue atacando.' Desactivado: el icono y el texto quedan vacíos."
-- 1.1.3 (Warlock raid gear option)
L["Raid Gear"] = "Equipo de banda"
L["Full raid gear rotation"] = "Rotación con equipo de banda completo"
L["Dungeons and raids only. Demonology skips Demonic Brand and the Decimation Soul Fire; Destruction skips Corruption on single targets. In full raid gear this is about 2% more damage on raid bosses, but less in pre-raid gear, so it is off by default"] = "Solo en mazmorras y bandas. Demonología omite Marca demoníaca y el Fuego de alma de Diezmar; Destrucción omite Corrupción contra un solo objetivo. Con equipo de banda completo es un 2% más de daño contra jefes de banda, pero menos con equipo previo a bandas, por eso está desactivado por defecto"
-- 1.1.3 (welcome tour: your class)
L["LazyGCore for your %s"] = "LazyGCore para la clase %s"
L["LazyGCore knows every spec of your class: the rotation, your buffs and reminders, and the talents that change what it suggests."] = "LazyGCore conoce cada especialización de tu clase: la rotación, tus beneficios y recordatorios, y los talentos que cambian lo que sugiere."
L["LazyGCore plays Arms, Fury and Protection with you: Sunder Armor stacks, Heroic Strike when you have rage to spare, threat when you tank, and Battle Shout kept up. It tips you when your weapon does not suit your talents, and LazyGCore's picks show the best build for leveling, dungeons, raids and PvP."] = "LazyGCore juega Armas, Furia y Protección contigo: acumulaciones de Hender armadura, Golpe heroico cuando te sobra ira, amenaza cuando tanqueas y Grito de guerra siempre activo. Te avisa cuando tu arma no encaja con tus talentos, y las recomendaciones de LazyGCore muestran la mejor build para subir de nivel, mazmorras, bandas y JcJ."
L["LazyGCore plays Retribution, Protection and Holy with you: Seals and Judgements in the right order, Holy Shield and Consecration when you tank, and for Holy a heal target picked from your party or raid, plus Cleanse when someone has a debuff you can remove. It reminds you of your Blessing and tips you when your weapon does not suit your talents."] = "LazyGCore juega Reprensión, Protección y Sagrado contigo: Sellos y Sentencias en el orden correcto, Escudo Sagrado y Consagración cuando tanqueas y, en Sagrado, un objetivo de curación elegido de tu grupo o banda, además de Purgación cuando alguien tiene un perjuicio que puedes quitar. Te recuerda tu Bendición y te avisa cuando tu arma no encaja con tus talentos."
L["LazyGCore plays Beast Mastery, Marksmanship and Survival with you: Hunter's Mark, Serpent Sting, Aimed Shot, Multi-Shot and your Hawks at the right time, and what to do when a mob reaches melee range. It reminds you about your pet and Mend Pet, and keeps the right Aspect up."] = "LazyGCore juega Dominio de bestias, Puntería y Supervivencia contigo: Marca del cazador, Aguijón de serpiente, Tiro de puntería, Multidisparo y tus halcones en el momento justo, y qué hacer cuando un enemigo llega al cuerpo a cuerpo. Te recuerda tu mascota y Sanar mascota, y mantiene el Aspecto correcto."
L["LazyGCore plays Assassination, Combat and Subtlety with you: it builds combo points and picks the finisher - Slice and Dice, Rupture or Eviscerate - at the number of points you choose. It reminds you to apply poisons, can suggest Vanish for damage, and tips you when your weapons do not suit your talents."] = "LazyGCore juega Asesinato, Combate y Sutileza contigo: acumula puntos de combo y elige el remate - Hacer picadillo, Ruptura o Eviscerar - con los puntos que tú elijas. Te recuerda aplicar venenos, puede sugerir Esfumar para hacer daño y te avisa cuando tus armas no encajan con tus talentos."
L["LazyGCore plays Shadow, Holy and Discipline with you. Shadow: Shadow Word: Pain, Mind Blast and Mind Flay in the right order, Shadow Word: Death at the health you choose, and Vampiric Embrace in raids. Holy and Discipline: a heal target picked from your party or raid and the right heal for it. It keeps Inner Fire and your buffs up."] = "LazyGCore juega Sombra, Sagrado y Disciplina contigo. Sombra: Palabra de las Sombras: Dolor, Explosión mental y Despelleje mental en el orden correcto, Palabra de las Sombras: muerte con la salud que elijas y Unirse a vampírica en bandas. Sagrado y Disciplina: un objetivo de curación elegido de tu grupo o banda y la curación adecuada. Mantiene Fuego interno y tus beneficios."
L["LazyGCore plays Elemental, Enhancement and Restoration with you: totems (Call of the Elements before dungeon and raid pulls), your weapon imbue and Water or Lightning Shield kept up, and for Restoration a heal target picked from your party or raid, with Chain Heal when several people are hurt."] = "LazyGCore juega Elemental, Mejora y Restauración contigo: tótems (Llamada de los elementos antes de los pulls en mazmorras y bandas), tu imbuición de arma y Escudo de agua o de relámpagos siempre activos y, en Restauración, un objetivo de curación elegido de tu grupo o banda, con Curación en cadena cuando hay varios heridos."
L["LazyGCore plays Arcane, Fire and Frost with you: Arcane Blast stacks, Scorch stacks for Fire, and your procs. It watches your mana with Mana Gems and Evocation, keeps Arcane Intellect and your armor up, tips you when your weapon does not suit your talents, and the cooldown icon shows when burst cooldowns and damage trinkets are ready."] = "LazyGCore juega Arcano, Fuego y Escarcha contigo: acumulaciones de Explosión Arcana, de Chamuscar para Fuego y tus procs. Vigila tu maná con gemas de maná y Evocación, mantiene Intelecto Arcano y tu armadura, te avisa cuando tu arma no encaja con tus talentos, y el icono de reutilización muestra cuándo están listos los cooldowns de ráfaga y los abalorios de daño."
L["LazyGCore plays Affliction, Demonology and Destruction with you: your Curse and Bane, Corruption and Immolate refreshed at the right time, and the filler that suits your talents. It suggests Life Tap when you run low on mana, reminds you to summon your demon and keep Demon Armor and your weapon stone up, and suggests Health Funnel when your demon is hurt."] = "LazyGCore juega Aflicción, Demonología y Destrucción contigo: tu Maldición y Perdición, Corrupción e Inmolar renovados en el momento justo y el relleno que encaja con tus talentos. Sugiere Transfusión de vida cuando te quedas sin maná, te recuerda invocar a tu demonio y mantener Armadura demoníaca y tu piedra de arma, y sugiere Cauce de salud cuando tu demonio está herido."
L["LazyGCore follows your form: Balance with Moonkin Form, Faerie Fire, Moonfire and Insect Swarm; Feral as a cat for damage or a bear for tanking; Restoration with a heal target picked from your party or raid and Rejuvenation kept rolling. It keeps Mark of the Wild and Thorns up."] = "LazyGCore sigue tu forma: Equilibrio con Forma de lechúcico lunar, Fuego feérico, Fuegolunar y Enjambre de insectos; Feral como felino para daño o como oso para tanquear; Restauración con un objetivo de curación elegido de tu grupo o banda y Rejuvenecimiento siempre activo. Mantiene Marca de lo salvaje y Espinas."

-- 1.1.4 (keybind size)
L["Custom keybind size"] = "Tamaño de atajo personalizado"
L["Lets you change the size of the keybind text on the main icon with Keybind Size. Off: the normal size that follows the icon size. Only applies when Show keybind is on."] = "Te permite cambiar el tamaño del texto del atajo en el icono principal con Tamaño del atajo. Desactivado: el tamaño normal, que sigue al tamaño del icono. Solo se aplica con Mostrar atajo activado."
L["Keybind Size"] = "Tamaño del atajo"
L["Size of the keybind text compared to normal (1.50 = 50% bigger). Up to 4 fills the whole icon; a big keybind moves to the centre. It never grows past the icon: a long keybind shrinks to fit. Only applies when Custom keybind size is on."] = "Tamaño del texto del atajo respecto al normal (1.50 = 50% más grande). Hasta 4 llena todo el icono; un atajo grande pasa al centro. Nunca supera el icono: un atajo largo se reduce para caber. Solo se aplica con Tamaño de atajo personalizado activado."

-- 1.1.5 (talent pick order)
L["Show the pick order on the talent frame"] = "Mostrar el orden en el panel de talentos"
L["Puts a number on every talent of your build that still needs points, in the order to take them (1 = next), on all trees, even when you have no point to spend."] = "Pone un número en cada talento de tu build que aún necesita puntos, en el orden en que debes cogerlos (1 = el siguiente), en todos los árboles, aunque no tengas puntos libres."
L["Pick numbers"] = "Números de orden"
L["How many upcoming talents get a number: the whole build (default) or only the next 3, 5 or 10. Only applies when Show the pick order on the talent frame is on."] = "Cuántos talentos próximos llevan número: toda la build (por defecto) o solo los próximos 3, 5 o 10. Solo se aplica con Mostrar el orden en el panel de talentos activado."
L["Whole build"] = "Toda la build"
L["Next 3"] = "Próximos 3"
L["Next 5"] = "Próximos 5"
L["Next 10"] = "Próximos 10"
